insert into activities (id, domain, age_band, title, why, duration_minutes, materials) values
  ('tummy-time-little-and-often', 'motor'::domain, 'm0_3'::age_band, 'Tummy time, little and often', 'A few short spells beat one long one. This is how neck and shoulder strength starts.', 5, 'A blanket on the floor'),
  ('let-them-grip-your-finger', 'motor'::domain, 'm0_3'::age_band, 'Let them grip your finger', 'The grasp reflex is their first piece of control. Your finger gives it something to practise on.', 5, 'Just your hand'),
  ('talk-them-through-it', 'communication'::domain, 'm0_3'::age_band, 'Talk them through it', 'Narrating what you''re doing bathes them in the rhythm of speech long before the words land.', 5, 'Whatever you''re already doing'),
  ('wait-after-you-speak', 'communication'::domain, 'm0_3'::age_band, 'Wait after you speak', 'Leaving a gap teaches them conversation has turns, even if theirs is only a wriggle.', 5, 'Nothing at all'),
  ('follow-the-slow-object', 'cognitive'::domain, 'm0_3'::age_band, 'Follow the slow object', 'Tracking something across their view is the first visual skill they build.', 5, 'A soft toy, or your face'),
  ('light-and-shadow', 'cognitive'::domain, 'm0_3'::age_band, 'Light and shadow', 'Contrast is most of what they can see right now. Slow changes in light genuinely hold them.', 5, 'A window and a curtain'),
  ('face-to-face-close-up', 'social_emotional'::domain, 'm0_3'::age_band, 'Face to face, close up', 'At this age they focus about 30cm away — roughly the distance to your face while feeding.', 5, 'Just the two of you'),
  ('answer-every-cry', 'social_emotional'::domain, 'm0_3'::age_band, 'Answer every cry', 'Responding consistently is how they learn the world is safe. You cannot spoil a newborn.', 5, 'Only your attention'),
  ('reach-for-it', 'motor'::domain, 'm4_6'::age_band, 'Reach for it', 'Holding a toy just within reach turns a swipe into a deliberate grab.', 10, 'A rattle or soft toy'),
  ('roll-with-a-little-help', 'motor'::domain, 'm4_6'::age_band, 'Roll with a little help', 'A gentle hand at the hip shows them the movement their body is already trying to find.', 10, 'A flat, soft surface'),
  ('copy-their-sounds-back', 'communication'::domain, 'm4_6'::age_band, 'Copy their sounds back', 'Echoing their babble teaches turn-taking — the shape of conversation before the words arrive.', 10, 'Nothing at all'),
  ('sing-the-same-song-daily', 'communication'::domain, 'm4_6'::age_band, 'Sing the same song daily', 'Repetition is what makes language stick. The same song each day gives them something to predict.', 10, 'Your voice, however it sounds'),
  ('two-textures-one-hand', 'cognitive'::domain, 'm4_6'::age_band, 'Two textures, one hand', 'Something soft, then something crinkly, builds the sense of touch they''ll learn everything else with.', 10, 'A muslin cloth and paper'),
  ('mirror-time', 'cognitive'::domain, 'm4_6'::age_band, 'Mirror time', 'They won''t know it''s them yet, but a face that moves when they move is worth studying.', 10, 'Any mirror'),
  ('exaggerate-your-face', 'social_emotional'::domain, 'm4_6'::age_band, 'Exaggerate your face', 'Big, slow expressions are readable to them now, and copying yours is their first social skill.', 10, 'Just the two of you'),
  ('let-them-lead-the-game', 'social_emotional'::domain, 'm4_6'::age_band, 'Let them lead the game', 'Pausing when they look away and resuming when they return teaches them their signals matter.', 10, 'Nothing at all'),
  ('cruising-along-the-sofa', 'motor'::domain, 'm7_12'::age_band, 'Cruising along the sofa', 'Furniture at chest height gives them something to pull along while their legs get confident.', 10, 'A low sofa or table'),
  ('pincer-practice-with-snacks', 'motor'::domain, 'm7_12'::age_band, 'Pincer practice with snacks', 'Picking up small pieces trains the finger-and-thumb grip they''ll one day write with.', 10, 'Soft finger food'),
  ('name-what-they-point-at', 'communication'::domain, 'm7_12'::age_band, 'Name what they point at', 'They''re pointing before they''re speaking. Naming it turns the gesture into a word.', 10, 'The room you''re in'),
  ('wave-clap-repeat', 'communication'::domain, 'm7_12'::age_band, 'Wave, clap, repeat', 'Gestures come before speech. Every wave they copy is a word forming.', 10, 'Just your hands'),
  ('peek-a-boo-three-ways', 'cognitive'::domain, 'm7_12'::age_band, 'Peek-a-boo, three ways', 'Object permanence is clicking into place right now — this is that idea, as a game.', 10, 'A scarf and your hands'),
  ('in-and-out-of-the-box', 'cognitive'::domain, 'm7_12'::age_band, 'In and out of the box', 'Emptying and filling the same container is real research into how space works.', 10, 'A box and safe objects'),
  ('stay-in-sight-move-away-slowly', 'social_emotional'::domain, 'm7_12'::age_band, 'Stay in sight, move away slowly', 'Short, visible separations build the trust that you always come back.', 10, 'Your own home'),
  ('name-what-they-re-feeling', 'social_emotional'::domain, 'm7_12'::age_band, 'Name what they''re feeling', 'Putting a word to a wobble is how feelings become manageable later on.', 5, 'Only your attention'),
  ('one-bowl-sorting', 'motor'::domain, 'm13_24'::age_band, 'One-bowl sorting', 'Sorting is the earliest form of staying with one thing — the beginning of focus.', 10, 'A bowl and two spoons'),
  ('push-something-heavy', 'motor'::domain, 'm13_24'::age_band, 'Push something heavy', 'Pushing a loaded basket builds the whole-body strength that walking still needs.', 10, 'A basket with books in it'),
  ('give-them-the-word-they-re-reaching-for', 'communication'::domain, 'm13_24'::age_band, 'Give them the word they''re reaching for', 'Answering the gesture with the word closes the gap between wanting and asking.', 10, 'The room you''re in'),
  ('two-word-echo', 'communication'::domain, 'm13_24'::age_band, 'Two-word echo', 'When they say one word, hand back two. That''s the next step, offered rather than demanded.', 10, 'Nothing at all'),
  ('the-mystery-bag', 'cognitive'::domain, 'm13_24'::age_band, 'The mystery bag', 'Reaching in without looking makes them predict before they see — ten quiet minutes of curiosity.', 10, 'A bag and 3 objects'),
  ('which-cup-is-it-under', 'cognitive'::domain, 'm13_24'::age_band, 'Which cup is it under?', 'Hiding something in plain sight lets them hold an idea in mind and then act on it.', 10, 'Two cups and a small toy'),
  ('let-them-help-with-a-real-job', 'social_emotional'::domain, 'm13_24'::age_band, 'Let them help with a real job', 'Carrying something to the bin is small, real, and theirs. Usefulness is a feeling they can have now.', 10, 'Whatever you''re doing'),
  ('name-the-big-feeling-then-wait', 'social_emotional'::domain, 'm13_24'::age_band, 'Name the big feeling, then wait', 'Naming a tantrum without rushing to fix it teaches them feelings pass on their own.', 10, 'Only your patience'),
  ('build-it-then-rebuild-it', 'motor'::domain, 'm25_36'::age_band, 'Build it, then rebuild it', 'Rebuilding the same tower stretches attention gently, without it feeling like a test.', 15, 'Anything stackable'),
  ('balance-along-a-line', 'motor'::domain, 'm25_36'::age_band, 'Balance along a line', 'A line on the floor turns walking into a challenge they can feel themselves getting better at.', 15, 'A strip of tape'),
  ('tell-me-the-story-back', 'communication'::domain, 'm25_36'::age_band, 'Tell me the story back', 'Retelling a familiar book grows memory and language at the same time.', 15, 'A favourite picture book'),
  ('the-and-then-game', 'communication'::domain, 'm25_36'::age_band, 'The ''and then?'' game', 'One extra question at a time stretches a two-word answer into a sentence.', 15, 'Nothing — a walk works'),
  ('sort-by-one-thing', 'cognitive'::domain, 'm25_36'::age_band, 'Sort by one thing', 'Choosing a single rule — all the red ones — is the start of real categorising.', 15, 'Socks, blocks, or buttons'),
  ('what-s-missing', 'cognitive'::domain, 'm25_36'::age_band, 'What''s missing?', 'Taking one object from a small group asks them to hold a picture in their head.', 15, 'Three familiar objects'),
  ('take-turns-on-purpose', 'social_emotional'::domain, 'm25_36'::age_band, 'Take turns on purpose', 'Waiting is hard now. Short, obvious turns make it practisable rather than punishing.', 15, 'Any one toy'),
  ('offer-two-real-choices', 'social_emotional'::domain, 'm25_36'::age_band, 'Offer two real choices', 'Two options you can both live with gives them control without opening up the whole day.', 10, 'Whatever you''re deciding'),
  ('hop-then-hop-further', 'motor'::domain, 'y3_5'::age_band, 'Hop, then hop further', 'One foot at a time is a balance problem they can now solve, and enjoy solving.', 15, 'A bit of open floor'),
  ('cut-along-the-line', 'motor'::domain, 'y3_5'::age_band, 'Cut along the line', 'Scissors ask each hand to do a different job at once — harder than it looks, and worth practising.', 15, 'Safety scissors, old paper'),
  ('the-question-game', 'communication'::domain, 'y3_5'::age_band, 'The question game', 'Letting them ask you the questions flips the usual direction and stretches how they build ideas.', 15, 'Nothing — a walk works'),
  ('tell-it-in-order', 'communication'::domain, 'y3_5'::age_band, 'Tell it in order', 'Retelling their day in sequence is where storytelling and memory meet.', 15, 'The day you''ve just had'),
  ('what-floats-what-sinks', 'cognitive'::domain, 'y3_5'::age_band, 'What floats, what sinks?', 'They''re old enough to guess before they test — that''s the beginning of real reasoning.', 15, 'A bowl of water, small things'),
  ('sort-it-two-different-ways', 'cognitive'::domain, 'y3_5'::age_band, 'Sort it two different ways', 'The same objects grouped by colour, then by size, shows them a rule is a choice.', 15, 'Buttons, blocks, or leaves'),
  ('how-do-you-think-they-felt', 'social_emotional'::domain, 'y3_5'::age_band, 'How do you think they felt?', 'Asking about a character''s feelings is the safest possible practice for reading real ones.', 15, 'Any picture book'),
  ('make-the-rule-together', 'social_emotional'::domain, 'y3_5'::age_band, 'Make the rule together', 'A rule they helped write is one they can hold themselves to.', 15, 'Paper and a pen'),
  ('skip-gallop-then-swap', 'motor'::domain, 'y5_7'::age_band, 'Skip, gallop, then swap', 'Switching between patterns mid-go is coordination and attention working together.', 15, 'A bit of open space'),
  ('throw-and-catch-stepping-back', 'motor'::domain, 'y5_7'::age_band, 'Throw and catch, stepping back', 'Moving one step further apart each time makes the challenge theirs to set.', 15, 'Any soft ball'),
  ('teach-me-something', 'communication'::domain, 'y5_7'::age_band, 'Teach me something', 'Explaining something they know well is how understanding gets consolidated.', 15, 'Whatever they''re into'),
  ('explain-it-to-someone-younger', 'communication'::domain, 'y5_7'::age_band, 'Explain it to someone younger', 'Simplifying an idea for a smaller child is the hardest, most useful kind of explaining.', 15, 'A sibling, cousin, or toy'),
  ('plan-tomorrow-together', 'cognitive'::domain, 'y5_7'::age_band, 'Plan tomorrow together', 'Thinking a day ahead is real executive function practice, and it costs nothing.', 15, 'Paper and a pen'),
  ('what-would-happen-if', 'cognitive'::domain, 'y5_7'::age_band, 'What would happen if…?', 'Following a made-up change to its consequences is reasoning without a right answer.', 15, 'Nothing at all'),
  ('what-would-you-do', 'social_emotional'::domain, 'y5_7'::age_band, 'What would you do?', 'Talking through a tricky moment before it happens gives them something to reach for when it does.', 15, 'A moment from their week'),
  ('notice-someone-else-s-day', 'social_emotional'::domain, 'y5_7'::age_band, 'Notice someone else''s day', 'Asking who had a hard day turns empathy from a feeling into a habit.', 15, 'Dinner, or the walk home')
insert into milestones (id, domain, age_band, stage_label, description, typical_age_min_months, typical_age_max_months, guide) values
  ('0-3-months-motor-lifts-head-briefly-when-on-tummy', 'motor'::domain, 'm0_3'::age_band, '0–3 months', 'Lifts head briefly when on tummy', 0, 3, '{"try":"Do tummy time for 1–2 minutes several times a day on a firm surface. Get down to her eye level — she’ll try harder to lift her head to see your face.","watch":"Head wobbles up even briefly; she strains toward your face during tummy time.","see":"Head shows no lifting at all by 3 months, or neck feels unusually floppy."}'::jsonb),
  ('0-3-months-motor-moves-arms-and-legs-symmetrically', 'motor'::domain, 'm0_3'::age_band, '0–3 months', 'Moves arms and legs symmetrically', 0, 3, '{"try":"Lay her on her back and gently cycle her limbs in slow, smooth motions. Bath time is ideal — warm water makes movement easier.","watch":"Both sides move with similar frequency and strength during awake time.","see":"One side consistently moves much less than the other, or limbs seem very stiff or very floppy."}'::jsonb),
  ('0-3-months-motor-brings-hands-near-face', 'motor'::domain, 'm0_3'::age_band, '0–3 months', 'Brings hands near face', 0, 3, '{"try":"Keep mittens off during awake time so she can discover her hands. Gently guide her hands toward her face so she experiences the sensation.","watch":"Hands drift toward her mouth or face during relaxed, alert moments.","see":"No hand-to-face movement by 3 months alongside other motor concerns."}'::jsonb),
  ('0-3-months-communication-cries-to-express-needs', 'communication'::domain, 'm0_3'::age_band, '0–3 months', 'Cries to express needs', 0, 3, '{"try":"Respond consistently and promptly to every cry in these early months. Reliable responses build trust and, over time, actually reduce overall crying.","watch":"Different cry patterns begin to emerge for hunger, discomfort, and tiredness.","see":"Baby rarely cries even when hungry or uncomfortable, or the cry is consistently very weak or high-pitched."}'::jsonb),
  ('0-3-months-communication-coos-and-makes-soft-sounds', 'communication'::domain, 'm0_3'::age_band, '0–3 months', 'Coos and makes soft sounds', 0, 3, '{"try":"When she makes a sound, pause and mimic it back — this serve-and-return teaches her communication is two-way. Talk and sing constantly.","watch":"Soft vowel-like sounds (ooh, aah) appear during calm, alert periods.","see":"No vocalisation other than crying by 3 months."}'::jsonb),
  ('0-3-months-communication-startles-at-loud-noises', 'communication'::domain, 'm0_3'::age_band, '0–3 months', 'Startles at loud noises', 0, 3, '{"try":"Test gently with a hand clap or rattle outside her line of sight when she is calm and awake. A clear startle confirms her hearing is active.","watch":"Eyes widen, arms briefly extend, or she startles visibly at sudden sounds.","see":"No startle response to loud sounds by 1 month warrants a hearing check."}'::jsonb),
  ('0-3-months-social_emotional-stares-at-faces-intently', 'social_emotional'::domain, 'm0_3'::age_band, '0–3 months', 'Stares at faces intently', 0, 3, '{"try":"Hold your face 20–30 cm away — that is the clearest focal distance for a newborn. Make slow, exaggerated expressions and give her time to lock on.","watch":"Eyes fix on your face and stay there; she may go still as she concentrates.","see":"No interest in faces by 6 weeks, especially combined with no eye contact."}'::jsonb),
  ('0-3-months-social_emotional-begins-to-smile-at-caregivers', 'social_emotional'::domain, 'm0_3'::age_band, '0–3 months', 'Begins to smile at caregivers', 0, 3, '{"try":"Smile broadly and slowly at her during calm awake time. The social smile typically emerges at 6–8 weeks. Increase face-to-face time if it hasn’t appeared.","watch":"A genuine smile — corners of mouth lift, cheeks engage — in response to your face or voice.","see":"No social smile by 3 months."}'::jsonb),
  ('0-3-months-social_emotional-calms-when-held-or-spoken-to', 'social_emotional'::domain, 'm0_3'::age_band, '0–3 months', 'Calms when held or spoken to', 0, 3, '{"try":"Try skin-to-skin holding, a familiar soft song, or placing her against your left chest so she hears your heartbeat. Consistency matters more than technique.","watch":"Crying reduces or stops when you pick her up, make eye contact, or speak calmly.","see":"Baby is consistently impossible to soothe — worth discussing to rule out reflux or other causes."}'::jsonb),
  ('0-3-months-cognitive-follows-moving-objects-with-eyes', 'cognitive'::domain, 'm0_3'::age_band, '0–3 months', 'Follows moving objects with eyes', 0, 3, '{"try":"Hold a high-contrast card or your face 25 cm away and move it slowly left to right. Give her time to lock on before moving.","watch":"Eyes track across the midline smoothly from one side to the other by 2–3 months.","see":"No visual tracking at all by 2 months, or significant eye crossing after 3 months."}'::jsonb),
  ('0-3-months-cognitive-recognises-familiar-voices', 'cognitive'::domain, 'm0_3'::age_band, '0–3 months', 'Recognises familiar voices', 0, 3, '{"try":"Speak to her from outside her line of sight and watch for her to turn her head or still in response. Use her name often in a warm tone.","watch":"She quiets, turns toward you, or shows alerting behaviour when she hears your voice.","see":"No response to voices or sounds by 3 months."}'::jsonb),
  ('0-3-months-cognitive-shows-interest-in-high-contrast-patterns', 'cognitive'::domain, 'm0_3'::age_band, '0–3 months', 'Shows interest in high-contrast patterns', 0, 3, '{"try":"Place black-and-white cards with stripes, checkers, or a bull’s-eye in her line of sight during alert periods. Swap them weekly to maintain novelty.","watch":"She gazes at the pattern and slows her movement to concentrate on it.","see":"No visual interest in anything in her environment by 2 months."}'::jsonb),
  ('4-6-months-motor-holds-head-steady-without-support', 'motor'::domain, 'm4_6'::age_band, '4–6 months', 'Holds head steady without support', 4, 6, '{"try":"Continue tummy time daily and add supported sitting on your lap so she practises balancing her head against gravity.","watch":"Head stays upright without bobbing during supported sitting; lifts fully during tummy time.","see":"Head still very floppy with no control by 4 months."}'::jsonb),
  ('4-6-months-motor-rolls-from-tummy-to-back', 'motor'::domain, 'm4_6'::age_band, '4–6 months', 'Rolls from tummy to back', 4, 6, '{"try":"Place a favourite toy just out of reach during tummy time to give her a reason to shift her weight. Never leave her unattended on an elevated surface now.","watch":"She shifts her weight to one side and rotates — tummy to back usually comes first.","see":"No rolling in either direction by 6 months."}'::jsonb),
  ('4-6-months-motor-reaches-and-grasps-toys', 'motor'::domain, 'm4_6'::age_band, '4–6 months', 'Reaches and grasps toys', 4, 6, '{"try":"Hold toys within easy reach and slightly off to one side. Dangle objects during tummy time — reaching while prone builds more muscle groups.","watch":"Intentional reach toward objects with the hand closing around them.","see":"No reaching or batting at objects by 5 months."}'::jsonb),
  ('4-6-months-motor-brings-objects-to-mouth', 'motor'::domain, 'm4_6'::age_band, '4–6 months', 'Brings objects to mouth', 4, 6, '{"try":"Offer safe teething toys and varied textures. Mouthing is important developmental exploration — her mouth is her most sensitive sensory tool at this age.","watch":"Grasped objects reliably make their way to the mouth with clear intention.","see":"Not typically a red flag alone, but flag if combined with very weak grasp or no hand use."}'::jsonb),
  ('4-6-months-communication-babbles-ba-da-ma-sounds', 'communication'::domain, 'm4_6'::age_band, '4–6 months', 'Babbles (ba, da, ma sounds)', 4, 6, '{"try":"Imitate her sounds back to her then add one new consonant sound. The more varied language input she hears, the richer her output will become.","watch":"Consonant-vowel combinations (ba, da, ma, ga) appear alongside cooing.","see":"No babbling or consonant sounds by 6 months."}'::jsonb),
  ('4-6-months-communication-responds-to-own-name', 'communication'::domain, 'm4_6'::age_band, '4–6 months', 'Responds to own name', 4, 6, '{"try":"Use her name consistently and pause after saying it to allow response time. Start with visual contact — let her see your face while you call her name.","watch":"She turns her head or looks toward you specifically when her name is called.","see":"No response to her own name by 6 months warrants a hearing check."}'::jsonb),
  ('4-6-months-communication-laughs-out-loud', 'communication'::domain, 'm4_6'::age_band, '4–6 months', 'Laughs out loud', 4, 6, '{"try":"Gentle tummy raspberries, peek-a-boo, and funny slow facial expressions are classic triggers. Find what she responds to most and repeat it often.","watch":"Belly laugh or sustained giggling during playful interaction with familiar people.","see":"No laughter or joyful vocalisations by 6 months."}'::jsonb),
  ('4-6-months-social_emotional-recognises-familiar-people', 'social_emotional'::domain, 'm4_6'::age_band, '4–6 months', 'Recognises familiar people', 4, 6, '{"try":"Ensure several consistent caregivers interact with her regularly. Vary your expressions deliberately — she is reading happy, surprised, and worried faces.","watch":"Clear preference for familiar faces; beginning to react differently to strangers.","see":"No differentiation between familiar and unfamiliar faces by 5 months."}'::jsonb),
  ('4-6-months-social_emotional-enjoys-playing-with-others', 'social_emotional'::domain, 'm4_6'::age_band, '4–6 months', 'Enjoys playing with others', 4, 6, '{"try":"Keep face-to-face sessions to 5–10 focused minutes. Songs with actions and simple back-and-forth exchanges are ideal at this age.","watch":"She smiles, vocalises, and reaches toward you during play.","see":"Consistently unresponsive to social play — worth mentioning at your check-up."}'::jsonb),
  ('4-6-months-social_emotional-shows-displeasure-when-play-stops', 'social_emotional'::domain, 'm4_6'::age_band, '4–6 months', 'Shows displeasure when play stops', 4, 6, '{"try":"Build anticipation by pausing mid-game and making a ‘what’s next?’ face before continuing. This teaches her that interaction is reciprocal.","watch":"Fussing, reaching, or vocalising when an engaging activity or interaction stops.","see":"No emotional response to changes in social interaction by 6 months."}'::jsonb),
  ('4-6-months-cognitive-interested-in-mirror-reflections', 'cognitive'::domain, 'm4_6'::age_band, '4–6 months', 'Interested in mirror reflections', 4, 6, '{"try":"Hold a baby-safe mirror at face level and narrate: ‘Who’s that? That’s you!’ Move it slightly and watch her track the reflection.","watch":"She reaches for the reflection, smiles at it, or vocalises in response.","see":"No visual interest in reflections or faces in a mirror by 5 months."}'::jsonb),
  ('4-6-months-cognitive-explores-objects-with-hands-and-mouth', 'cognitive'::domain, 'm4_6'::age_band, '4–6 months', 'Explores objects with hands and mouth', 4, 6, '{"try":"Offer varied textures — silicone, wood, cloth, rubber. Supervised mouthing is safe and important; remove only genuinely hazardous items.","watch":"She grasps objects, turns them over, and brings them to her mouth with clear intent.","see":"Not exploring objects with hands at all by 5 months."}'::jsonb),
  ('4-6-months-cognitive-looks-for-fallen-objects-briefly', 'cognitive'::domain, 'm4_6'::age_band, '4–6 months', 'Looks for fallen objects briefly', 4, 6, '{"try":"Drop a toy while she is watching and say ‘Where did it go?’ Pause a few seconds before retrieving — you are building early object permanence.","watch":"Her gaze shifts downward to where the object fell, even briefly.","see":"Not a major concern at this stage; object permanence solidifies more at 7–9 months."}'::jsonb),
  ('7-9-months-motor-sits-without-support', 'motor'::domain, 'm7_12'::age_band, '7–9 months', 'Sits without support', 7, 9, '{"try":"Practise sitting on the floor with cushions around her. Sit facing her and hold out toys — reaching for them builds the balance muscles needed.","watch":"Sits steadily for several seconds without hands on the floor for support.","see":"Cannot sit even briefly with hands for support by 9 months."}'::jsonb),
  ('7-9-months-motor-begins-to-crawl-or-creep', 'motor'::domain, 'm7_12'::age_band, '7–9 months', 'Begins to crawl or creep', 7, 9, '{"try":"Place enticing toys just beyond reach during tummy time. Some babies bottom-shuffle or roll instead of crawling — all are valid ways of getting mobile.","watch":"Any method of moving forward on her own — crawl, creep, shuffle, or roll.","see":"No independent mobility of any kind by 12 months."}'::jsonb),
  ('7-9-months-motor-uses-pincer-grasp-thumb-finger', 'motor'::domain, 'm7_12'::age_band, '7–9 months', 'Uses pincer grasp (thumb + finger)', 7, 9, '{"try":"Scatter small safe objects (cereal puffs, soft diced fruit) on the high-chair tray and let her pick them up. This is perfect fine motor practice.","watch":"She picks up small objects using thumb and index finger rather than the whole palm.","see":"Only using a whole-palm rake grasp with no pincer development by 12 months."}'::jsonb),
  ('7-9-months-motor-pulls-to-stand-with-support', 'motor'::domain, 'm7_12'::age_band, '7–9 months', 'Pulls to stand with support', 7, 9, '{"try":"Place her hands on the edge of a low, stable table or sofa and encourage her to pull up. Stay close — falls are part of learning but shouldn’t be hard ones.","watch":"She uses furniture or your hands to pull herself up to standing.","see":"No attempt to bear weight on legs by 9 months."}'::jsonb),
  ('7-9-months-communication-imitates-sounds-and-gestures', 'communication'::domain, 'm7_12'::age_band, '7–9 months', 'Imitates sounds and gestures', 7, 9, '{"try":"Play imitation games: clap, bang, wave — then wait and watch. The game of ‘your turn, my turn’ directly builds her imitation ability.","watch":"She copies simple sounds and gestures you make, even with a short delay.","see":"No imitation of sounds or gestures by 9 months."}'::jsonb),
  ('7-9-months-communication-understands-no', 'communication'::domain, 'm7_12'::age_band, '7–9 months', 'Understands ''no''', 7, 9, '{"try":"Use ‘no’ sparingly and consistently, with a firm tone and clear body language. Reserve it for genuinely important moments so it carries meaning.","watch":"She pauses, looks at you, or changes her behaviour when you say ‘no’ firmly.","see":"Not a standalone concern; flag if combined with limited understanding of words or gestures."}'::jsonb),
  ('7-9-months-communication-waves-bye-bye', 'communication'::domain, 'm7_12'::age_band, '7–9 months', 'Waves bye-bye', 7, 9, '{"try":"Wave consistently whenever someone leaves. Pair it with ‘bye-bye’ every time and make it a cheerful, dramatic gesture she will want to copy.","watch":"She begins waving her hand (even approximately) at departure or when she hears ‘bye-bye’.","see":"No waving or pointing gestures by 12 months."}'::jsonb),
  ('7-9-months-communication-says-mama-or-dada-non-specific', 'communication'::domain, 'm7_12'::age_band, '7–9 months', 'Says ''mama'' or ''dada'' (non-specific)', 7, 9, '{"try":"Point to yourself and say ‘mama’ or ‘dada’ often. Label everything around her — more words heard means faster language development.","watch":"She produces these sounds frequently in babble — they don’t need to be directed at you yet.","see":"No babbling with varied consonants (ma, da, ba, ga) by 9 months."}'::jsonb),
  ('7-9-months-social_emotional-shows-stranger-anxiety', 'social_emotional'::domain, 'm7_12'::age_band, '7–9 months', 'Shows stranger anxiety', 7, 9, '{"try":"Never force contact with new people. Hold her in your arms while engaging warmly with the stranger yourself — she takes her cue from your calm.","watch":"Clinging, fussing, or crying with unfamiliar adults is completely normal and healthy at this age.","see":"No stranger anxiety at all — complete indifference to unfamiliar people — is worth noting."}'::jsonb),
  ('7-9-months-social_emotional-prefers-familiar-caregivers', 'social_emotional'::domain, 'm7_12'::age_band, '7–9 months', 'Prefers familiar caregivers', 7, 9, '{"try":"Ensure she has consistent primary caregivers. Brief separations with a reliable person practise the healthy attachment she is building.","watch":"Clear preference for familiar carers; settles more quickly with them.","see":"No preference for any caregiver at all by 9 months."}'::jsonb),
  ('7-9-months-social_emotional-plays-peek-a-boo', 'social_emotional'::domain, 'm7_12'::age_band, '7–9 months', 'Plays peek-a-boo', 7, 9, '{"try":"Play peek-a-boo many times a day — behind your hands, a cloth, a doorframe. This game directly teaches that things exist even when hidden.","watch":"She anticipates the reveal with smiles or excited vocalisations before you reappear.","see":"No enjoyment of or engagement with simple interactive games by 9 months."}'::jsonb),
  ('7-9-months-cognitive-searches-for-hidden-objects', 'cognitive'::domain, 'm7_12'::age_band, '7–9 months', 'Searches for hidden objects', 7, 9, '{"try":"Show her a toy then hide it under a cloth while she watches. Lift the cloth with a ‘found it!’ and repeat — you are directly building object permanence.","watch":"She pulls the cloth away or looks in the right place for the hidden toy.","see":"No searching for hidden objects by 9 months."}'::jsonb),
  ('7-9-months-cognitive-bangs-objects-together', 'cognitive'::domain, 'm7_12'::age_band, '7–9 months', 'Bangs objects together', 7, 9, '{"try":"Give her two objects that make satisfying sounds when banged — wooden spoons, cups, blocks. Demonstrate and let her copy.","watch":"She purposefully brings objects together with clear cause-and-effect exploration.","see":"Not typically isolated; flag if hand use is very limited overall."}'::jsonb),
  ('7-9-months-cognitive-points-at-objects-of-interest', 'cognitive'::domain, 'm7_12'::age_band, '7–9 months', 'Points at objects of interest', 7, 9, '{"try":"Point at objects yourself constantly, naming them: ‘Look — dog!’ She is learning to use pointing as communication.","watch":"She extends her index finger toward things she wants or finds interesting.","see":"No pointing or reaching toward objects of interest by 12 months."}'::jsonb),
  ('10-12-months-motor-stands-alone-briefly', 'motor'::domain, 'm7_12'::age_band, '10–12 months', 'Stands alone briefly', 10, 12, '{"try":"Practise letting go of support for a second or two while you stay close. Praise every attempt even if she immediately sits back down.","watch":"She releases her hold and balances unsupported for at least 1–2 seconds.","see":"Cannot bear weight on legs at all by 12 months."}'::jsonb),
  ('10-12-months-motor-cruises-along-furniture', 'motor'::domain, 'm7_12'::age_band, '10–12 months', 'Cruises along furniture', 10, 12, '{"try":"Arrange stable furniture so she has a safe route to cruise along. Place tempting toys at the far end to give her a goal.","watch":"She moves sideways along furniture with growing confidence and fewer stumbles.","see":"No attempt to move along furniture or bear weight by 12 months."}'::jsonb),
  ('10-12-months-motor-may-take-first-steps', 'motor'::domain, 'm7_12'::age_band, '10–12 months', 'May take first steps', 10, 12, '{"try":"Sit on the floor a step away, hold out your hands, and call her. Don’t rush — walking can arrive any time between 9 and 18 months and still be normal.","watch":"One, two, then a few steps independently before sitting or falling.","see":"Not walking independently by 18 months is the clinical threshold for evaluation."}'::jsonb),
  ('10-12-months-motor-feeds-self-finger-foods', 'motor'::domain, 'm7_12'::age_band, '10–12 months', 'Feeds self finger foods', 10, 12, '{"try":"Offer appropriately sized soft pieces (banana, well-cooked vegetables) on the high-chair tray. Let mealtimes be messy — it is fine motor work.","watch":"She picks up pieces intentionally and brings them to her mouth with growing accuracy.","see":"Not a developmental red flag alone; flag if combined with very limited hand coordination."}'::jsonb),
  ('10-12-months-communication-says-1-2-words-with-meaning', 'communication'::domain, 'm7_12'::age_band, '10–12 months', 'Says 1–2 words with meaning', 10, 12, '{"try":"Label objects and people consistently every day. When she says an approximation of a word, enthusiastically confirm it: ‘Yes! Ball!’","watch":"At least one word used consistently to mean the same thing — doesn’t need perfect pronunciation.","see":"No words with consistent meaning by 16 months warrants a speech check."}'::jsonb),
  ('10-12-months-communication-follows-simple-one-step-commands', 'communication'::domain, 'm7_12'::age_band, '10–12 months', 'Follows simple one-step commands', 10, 12, '{"try":"Give simple commands with gesture: ‘Give me the cup’ while holding out your hand. Pair words with clear actions every time at first.","watch":"She follows the instruction without you needing to physically guide her.","see":"No response to simple commands (with or without gesture) by 12 months."}'::jsonb),
  ('10-12-months-communication-uses-gestures-to-communicate', 'communication'::domain, 'm7_12'::age_band, '10–12 months', 'Uses gestures to communicate', 10, 12, '{"try":"Respond meaningfully to every gesture she makes — if she points, name the object and respond. This teaches her gestures have power.","watch":"Pointing, reaching, waving, and head-shaking used with clear communicative intent.","see":"No communicative gestures at all by 12 months."}'::jsonb),
  ('10-12-months-social_emotional-imitates-actions-in-play', 'social_emotional'::domain, 'm7_12'::age_band, '10–12 months', 'Imitates actions in play', 10, 12, '{"try":"Demonstrate simple actions: stir a bowl, talk on a toy phone, drive a toy car. Then hand it to her and wait — imitation is how she learns.","watch":"She copies actions she has seen adults do, even with a delay of hours.","see":"No imitative play at all by 12 months."}'::jsonb),
  ('10-12-months-social_emotional-shows-affection-to-familiar-people', 'social_emotional'::domain, 'm7_12'::age_band, '10–12 months', 'Shows affection to familiar people', 10, 12, '{"try":"Model affection openly — hug, kiss, cuddle her freely. She learns emotional expression by seeing it, not just receiving it.","watch":"Leans in for hugs, pats faces, shows physical affection spontaneously.","see":"Consistently avoids physical affection with familiar people by 12 months."}'::jsonb),
  ('10-12-months-social_emotional-tests-caregiver-reactions', 'social_emotional'::domain, 'm7_12'::age_band, '10–12 months', 'Tests caregiver reactions', 10, 12, '{"try":"Stay consistent and calm — if you react dramatically, she will repeat the behaviour for the reaction. A neutral response is often most effective.","watch":"She looks at your face before, during, or after doing something she knows is off-limits.","see":"This is completely healthy developmental behaviour — not a concern."}'::jsonb),
  ('10-12-months-cognitive-understands-object-permanence', 'cognitive'::domain, 'm7_12'::age_band, '10–12 months', 'Understands object permanence', 10, 12, '{"try":"Play hide-and-seek with toys under cups or cloths. Progress from transparent to opaque to make it gradually harder.","watch":"She looks in the right location for a hidden toy, even when moved to a new spot.","see":"No search for hidden objects by 12 months."}'::jsonb),
  ('10-12-months-cognitive-explores-cause-and-effect', 'cognitive'::domain, 'm7_12'::age_band, '10–12 months', 'Explores cause and effect', 10, 12, '{"try":"Offer toys with clear cause-and-effect: drop things into containers, bang drums, press buttons that light up. Let her repeat to her heart’s content.","watch":"She deliberately repeats actions that produce interesting results.","see":"No intentional cause-and-effect play by 12 months."}'::jsonb),
  ('10-12-months-cognitive-puts-objects-into-containers', 'cognitive'::domain, 'm7_12'::age_band, '10–12 months', 'Puts objects into containers', 10, 12, '{"try":"Give her a container and small blocks and demonstrate dropping them in. Say ‘in!’ each time, then let her try independently.","watch":"She drops objects into containers with clear intent, and may tip them out to repeat.","see":"No object manipulation or container play by 12 months."}'::jsonb),
  ('12-15-months-motor-takes-first-independent-steps', 'motor'::domain, 'm7_12'::age_band, '12–15 months', 'Takes first independent steps', 12, 15, '{"try":"Sit a step away, hold out your hands, and call her. Walking can arrive anywhere from 9 to 18 months and still be normal — there''s no need to rush it.","watch":"One, two, then a few steps independently before sitting or falling.","see":"No attempt at independent steps by 15 months, alongside no cruising either."}'::jsonb),
  ('12-15-months-motor-stands-alone-briefly', 'motor'::domain, 'm7_12'::age_band, '12–15 months', 'Stands alone briefly', 12, 15, '{"try":"Practise letting go of support for a second or two while staying close. Praise every attempt even if she sits straight back down.","watch":"She releases her hold and balances unsupported for at least 1–2 seconds.","see":"Cannot bear weight on legs at all by 15 months."}'::jsonb),
  ('12-15-months-motor-stacks-two-blocks', 'motor'::domain, 'm7_12'::age_band, '12–15 months', 'Stacks two blocks', 12, 15, '{"try":"Demonstrate stacking one block on another slowly, then hand her the next block and wait. A flat, stable surface makes this much easier.","watch":"She places one block on top of another, even if it topples right after.","see":"No attempt to stack or manipulate blocks by 15 months."}'::jsonb),
  ('12-15-months-communication-says-1-3-words-with-meaning', 'communication'::domain, 'm7_12'::age_band, '12–15 months', 'Says 1–3 words with meaning', 12, 15, '{"try":"Label objects and people consistently every day. When she says an approximation of a word, confirm it warmly: ‘Yes! Ball!’","watch":"At least one word used consistently to mean the same thing — pronunciation doesn''t need to be perfect.","see":"No words with consistent meaning by 15 months."}'::jsonb),
  ('12-15-months-communication-points-to-request-an-object', 'communication'::domain, 'm7_12'::age_band, '12–15 months', 'Points to request an object', 12, 15, '{"try":"Respond meaningfully every time she points — name the object and hand it over. This teaches her that pointing has real communicative power.","watch":"She extends her index finger toward something she wants, checking your face for a response.","see":"No pointing or reaching to communicate by 15 months."}'::jsonb),
  ('12-15-months-communication-follows-a-one-step-command-with-a-gesture', 'communication'::domain, 'm7_12'::age_band, '12–15 months', 'Follows a one-step command with a gesture', 12, 15, '{"try":"Pair a simple instruction with a clear gesture: ‘Give me the cup’ while holding out your hand.","watch":"She completes the action when word and gesture are given together.","see":"No response to simple requests, even gestured, by 15 months."}'::jsonb),
  ('12-15-months-social_emotional-shows-clear-preference-for-a-primary-caregiver', 'social_emotional'::domain, 'm7_12'::age_band, '12–15 months', 'Shows clear preference for a primary caregiver', 12, 15, '{"try":"This is healthy attachment, not favouritism to worry about. Continue building warm one-to-one time with every caregiver in the family.","watch":"She reaches for, calms fastest with, or seeks out one particular person when upset.","see":"No differentiated attachment to any caregiver by 15 months."}'::jsonb),
  ('12-15-months-social_emotional-imitates-simple-actions-like-clapping', 'social_emotional'::domain, 'm7_12'::age_band, '12–15 months', 'Imitates simple actions like clapping', 12, 15, '{"try":"Play simple copying games — clap, wave, pat your head — and pause for her to try. Repetition across many days is what makes it click.","watch":"She copies a simple gesture you make, even a few seconds later.","see":"No imitation of any gestures or actions by 15 months."}'::jsonb),
  ('12-15-months-social_emotional-seeks-comfort-when-hurt-or-scared', 'social_emotional'::domain, 'm7_12'::age_band, '12–15 months', 'Seeks comfort when hurt or scared', 12, 15, '{"try":"Respond promptly and warmly every time she''s distressed. Reliable comfort now builds the security she''ll draw on for independence later.","watch":"She reaches for or crawls/walks toward a caregiver when hurt, tired, or startled.","see":"No seeking of comfort from any caregiver when distressed by 15 months."}'::jsonb),
  ('12-15-months-cognitive-finds-an-object-after-watching-it-hidden', 'cognitive'::domain, 'm7_12'::age_band, '12–15 months', 'Finds an object after watching it hidden', 12, 15, '{"try":"Hide a toy under a cup while she watches, then say ‘where did it go?’ and let her search.","watch":"She lifts the cup or looks in the right place for the hidden toy.","see":"No searching for hidden objects by 15 months."}'::jsonb),
  ('12-15-months-cognitive-explores-objects-by-turning-banging-dropping', 'cognitive'::domain, 'm7_12'::age_band, '12–15 months', 'Explores objects by turning, banging, dropping', 12, 15, '{"try":"Offer a variety of safe household objects — measuring cups, wooden spoons — alongside toys. Let her investigate at her own pace.","watch":"She turns objects over, bangs them together, or drops them repeatedly with clear curiosity.","see":"No exploratory object play at all by 15 months."}'::jsonb),
  ('12-15-months-cognitive-drinks-from-an-open-cup-with-help', 'cognitive'::domain, 'm7_12'::age_band, '12–15 months', 'Drinks from an open cup with help', 12, 15, '{"try":"Offer a small amount of water in a small open cup, hands over hands at first. Expect spills — this is normal practice, not a mess to prevent.","watch":"She tips the cup toward her mouth and swallows with your hands guiding.","see":"No interest in or attempt at cup drinking by 15 months, alongside other feeding concerns."}'::jsonb),
  ('15-18-months-motor-walks-steadily-without-support', 'motor'::domain, 'm13_24'::age_band, '15–18 months', 'Walks steadily without support', 15, 18, '{"try":"Give her plenty of open floor space and let her practise without constantly holding her hands. Uneven surfaces like grass build balance fast.","watch":"Confident walking with fewer falls and better balance week over week.","see":"Not walking independently at all by 18 months."}'::jsonb),
  ('15-18-months-motor-climbs-onto-low-furniture', 'motor'::domain, 'm13_24'::age_band, '15–18 months', 'Climbs onto low furniture', 15, 18, '{"try":"Allow supervised climbing on low, stable surfaces — a small foam step or low platform works well.","watch":"She manoeuvres herself onto a low sofa or step with some effort.","see":"Extremely limited gross motor activity overall by 18 months."}'::jsonb),
  ('15-18-months-motor-scribbles-spontaneously-with-a-crayon', 'motor'::domain, 'm13_24'::age_band, '15–18 months', 'Scribbles spontaneously with a crayon', 15, 18, '{"try":"Tape paper to the floor and offer a large, chunky crayon. The floor position gives more control than a table at this age.","watch":"Any intentional mark-making, even random lines — the intent is what matters, not the picture.","see":"No interest in mark-making tools or very weak hand grip by 18 months."}'::jsonb),
  ('15-18-months-communication-vocabulary-of-5-10-words', 'communication'::domain, 'm13_24'::age_band, '15–18 months', 'Vocabulary of 5–10 words', 15, 18, '{"try":"Read board books daily and name every picture. Expand what she says — if she says ‘dog’, you say ‘big brown dog!’","watch":"New words appearing steadily, even rough approximations that are used consistently.","see":"Fewer than 3 words by 18 months, or any loss of previously used words, warrants evaluation."}'::jsonb),
  ('15-18-months-communication-points-to-at-least-one-body-part-on-request', 'communication'::domain, 'm13_24'::age_band, '15–18 months', 'Points to at least one body part on request', 15, 18, '{"try":"Play naming games during bath time or dressing: ‘where''s your nose?’ Point to your own first, then hers.","watch":"She points to or touches a named body part, even if only one or two consistently.","see":"No response to any ‘where''s your…’ questions by 18 months."}'::jsonb),
  ('15-18-months-communication-combines-a-gesture-with-a-word-to-request', 'communication'::domain, 'm13_24'::age_band, '15–18 months', 'Combines a gesture with a word to request', 15, 18, '{"try":"Model the pairing yourself — say ‘up’ while reaching your arms up. She''ll pick up the combination through repetition.","watch":"She reaches or points while saying a word, rather than using either alone.","see":"No combined gesture-and-word requests by 18 months."}'::jsonb),
  ('15-18-months-social_emotional-asserts-me-or-mine-over-toys', 'social_emotional'::domain, 'm13_24'::age_band, '15–18 months', 'Asserts ‘me’ or ‘mine’ over toys', 15, 18, '{"try":"Offer controlled choices — ‘the red cup or the blue cup?’ — which satisfies the autonomy drive while you stay in charge.","watch":"Strong assertions of ownership and preference — this is healthy, not defiance.","see":"This is healthy developmental behaviour — not a concern on its own."}'::jsonb),
  ('15-18-months-social_emotional-plays-alone-contentedly-for-short-stretches', 'social_emotional'::domain, 'm13_24'::age_band, '15–18 months', 'Plays alone contentedly for short stretches', 15, 18, '{"try":"Set up an inviting, safe play space and resist jumping in immediately. A few minutes of independent play is a genuine skill being built.","watch":"She engages with a toy or activity on her own for several minutes without needing you.","see":"Cannot settle into any independent play at all by 18 months."}'::jsonb),
  ('15-18-months-social_emotional-shows-affection-unprompted', 'social_emotional'::domain, 'm13_24'::age_band, '15–18 months', 'Shows affection unprompted', 15, 18, '{"try":"Model affection openly — hugs, kisses, gentle pats — so she has a rich example to draw from.","watch":"She leans in for a hug, pats your face, or offers a spontaneous kiss.","see":"Consistently avoids or resists all physical affection by 18 months."}'::jsonb),
  ('15-18-months-cognitive-uses-a-spoon-with-some-spilling', 'cognitive'::domain, 'm13_24'::age_band, '15–18 months', 'Uses a spoon with some spilling', 15, 18, '{"try":"Offer a small spoon and thick foods like yoghurt that stick well. Expect mess — it''s the practice that matters, not the outcome.","watch":"She scoops and brings the spoon to her mouth, even if half the food falls off.","see":"No attempt to self-feed with any utensil by 18 months."}'::jsonb),
  ('15-18-months-cognitive-matches-simple-shapes-to-a-shape-sorter', 'cognitive'::domain, 'm13_24'::age_band, '15–18 months', 'Matches simple shapes to a shape sorter', 15, 18, '{"try":"Start with just one or two shapes at a time rather than the full set. Guide her hand through the motion once before stepping back.","watch":"She attempts to fit a shape into its matching hole, even with trial and error.","see":"No interest in or attempt at shape-fitting toys by 18 months."}'::jsonb),
  ('15-18-months-cognitive-points-to-named-pictures-in-a-book', 'cognitive'::domain, 'm13_24'::age_band, '15–18 months', 'Points to named pictures in a book', 15, 18, '{"try":"Ask ‘where''s the cat?’ while reading and give her a moment to point before turning the page.","watch":"She points to a named picture in a familiar book with increasing accuracy.","see":"No response to simple picture-naming questions by 18 months."}'::jsonb),
  ('18-21-months-motor-runs-stiffly', 'motor'::domain, 'm13_24'::age_band, '18–21 months', 'Runs stiffly', 18, 21, '{"try":"Encourage active outdoor play on grass or soft ground, which is more forgiving than hard indoor floors for a still-wobbly run.","watch":"She moves faster than a walk with a brief flight phase — at least one foot off the ground.","see":"Not walking steadily by 21 months, or falling in a way that isn''t improving."}'::jsonb),
  ('18-21-months-motor-kicks-a-stationary-ball', 'motor'::domain, 'm13_24'::age_band, '18–21 months', 'Kicks a stationary ball', 18, 21, '{"try":"Place a large, soft ball right by her feet and demonstrate a gentle kick first. Large slow balls are far easier to connect with than small ones.","watch":"She swings a leg and makes intentional contact with the ball.","see":"No ball play or lower-body coordination by 21 months."}'::jsonb),
  ('18-21-months-motor-walks-up-steps-holding-a-rail-both-feet-per-step', 'motor'::domain, 'm13_24'::age_band, '18–21 months', 'Walks up steps holding a rail, both feet per step', 18, 21, '{"try":"Hold her hand or let her use a rail on real stairs when supervised. Narrate: ‘up, up, up.’","watch":"She climbs steps one at a time, both feet landing on each step before the next.","see":"No attempt to climb stairs with support by 21 months."}'::jsonb),
  ('18-21-months-communication-vocabulary-of-roughly-20-words', 'communication'::domain, 'm13_24'::age_band, '18–21 months', 'Vocabulary of roughly 20 words', 18, 21, '{"try":"Narrate your day constantly — more words heard consistently means faster vocabulary growth. Name everything you touch, use, or pass.","watch":"New words appearing weekly, even rough or partial pronunciations used consistently.","see":"Fewer than 10 words by 21 months, or any loss of words, warrants evaluation."}'::jsonb),
  ('18-21-months-communication-combines-a-word-and-gesture-into-simple-requests', 'communication'::domain, 'm13_24'::age_band, '18–21 months', 'Combines a word and gesture into simple requests', 18, 21, '{"try":"Respond to combined requests warmly and promptly — ‘up’ plus reaching arms means she wants to be picked up. Confirm it in words back.","watch":"She reliably pairs a gesture with a word to make her wants clear.","see":"No combined communicative attempts of any kind by 21 months."}'::jsonb),
  ('18-21-months-communication-follows-a-familiar-2-step-routine-with-prompting', 'communication'::domain, 'm13_24'::age_band, '18–21 months', 'Follows a familiar 2-step routine with prompting', 18, 21, '{"try":"Use the same two-step routine daily — ‘get your shoes, bring them here’ — so the pattern becomes predictable.","watch":"She completes both familiar steps with a gentle reminder partway through.","see":"Not following even a one-step instruction by 21 months."}'::jsonb),
  ('18-21-months-social_emotional-plays-alongside-another-child-parallel-play', 'social_emotional'::domain, 'm13_24'::age_band, '18–21 months', 'Plays alongside another child (parallel play)', 18, 21, '{"try":"Arrange playdates with similar toys for each child, side by side. Don''t force sharing or turn-taking yet — this stage is about comfortable proximity.","watch":"She plays contentedly near another child, aware of them without directly interacting.","see":"Complete disinterest in or distress around other children by 21 months."}'::jsonb),
  ('18-21-months-social_emotional-shows-a-wide-range-of-clear-emotions', 'social_emotional'::domain, 'm13_24'::age_band, '18–21 months', 'Shows a wide range of clear emotions', 18, 21, '{"try":"Name emotions as they show up: ‘you''re so happy about that!’ or ‘that made you upset.’ This is early groundwork for later self-regulation.","watch":"Clear, distinguishable expressions of joy, frustration, fear, and affection.","see":"Very flat or limited emotional expression by 21 months."}'::jsonb),
  ('18-21-months-social_emotional-begins-to-test-limits-deliberately', 'social_emotional'::domain, 'm13_24'::age_band, '18–21 months', 'Begins to test limits deliberately', 18, 21, '{"try":"Stay calm and consistent — dramatic reactions tend to reinforce the very behaviour you''re hoping to reduce.","watch":"She looks at your face while doing something she knows is off-limits, gauging your reaction.","see":"This is healthy, expected developmental behaviour — not a concern."}'::jsonb),
  ('18-21-months-cognitive-sorts-objects-into-two-groups-with-help', 'cognitive'::domain, 'm13_24'::age_band, '18–21 months', 'Sorts objects into two groups with help', 18, 21, '{"try":"Sort laundry together — ‘socks here, shirts there’ — guiding her hand at first before letting her try alone.","watch":"She places an object in the correct group with a prompt or light guidance.","see":"No sorting attempt at all, even with heavy guidance, by 21 months."}'::jsonb),
  ('18-21-months-cognitive-completes-a-simple-2-3-piece-puzzle', 'cognitive'::domain, 'm13_24'::age_band, '18–21 months', 'Completes a simple 2–3 piece puzzle', 18, 21, '{"try":"Start with single-piece inset puzzles before moving to 2–3 pieces. Guide her hand through the motion once before stepping back.","watch":"She attempts and sometimes completes a simple puzzle with trial and error.","see":"No problem-solving play with fit-together toys by 21 months."}'::jsonb),
  ('18-21-months-cognitive-engages-in-brief-pretend-actions', 'cognitive'::domain, 'm13_24'::age_band, '18–21 months', 'Engages in brief pretend actions', 18, 21, '{"try":"Model simple pretend actions — feeding a doll, pushing a toy car — and hand her the toy to try herself.","watch":"She applies a pretend action to a toy that she''s seen applied to herself, like feeding a doll.","see":"No pretend or symbolic play at all by 21 months."}'::jsonb),
  ('21-24-months-motor-runs-with-better-control-stops-without-falling', 'motor'::domain, 'm13_24'::age_band, '21–24 months', 'Runs with better control, stops without falling', 21, 24, '{"try":"Give her open space to practise starting, running, and stopping — games like ‘red light, green light’ (even a very simple version) help.","watch":"She runs with more balance and can stop or change direction without toppling over.","see":"Not walking steadily or attempting to run at all by 24 months."}'::jsonb),
  ('21-24-months-motor-jumps-in-place-with-both-feet', 'motor'::domain, 'm13_24'::age_band, '21–24 months', 'Jumps in place with both feet', 21, 24, '{"try":"Demonstrate a small jump and count ‘1, 2, 3, jump!’ Make it playful — jumping on a soft mat or low step is a fun way to practise.","watch":"Both feet leave the ground together, even if it''s a very small hop.","see":"No jumping attempts of any kind by 24 months."}'::jsonb),
  ('21-24-months-motor-throws-a-ball-with-some-direction', 'motor'::domain, 'm13_24'::age_band, '21–24 months', 'Throws a ball with some direction', 21, 24, '{"try":"Stand close and make it a turn-taking game — she throws, you roll it back. Soft, light balls work best.","watch":"She lifts her arm and releases the ball with some forward intent.","see":"Very limited arm coordination or no throwing attempts by 24 months."}'::jsonb),
  ('21-24-months-communication-vocabulary-of-50-words', 'communication'::domain, 'm13_24'::age_band, '21–24 months', 'Vocabulary of 50+ words', 21, 24, '{"try":"Read daily and expand what she says — if she says ‘dog’, respond ‘big brown dog!’ This expansion technique measurably speeds vocabulary growth.","watch":"New words appearing regularly — even approximations count if used consistently.","see":"Fewer than 15 words by 24 months, or any vocabulary loss, warrants urgent evaluation."}'::jsonb),
  ('21-24-months-communication-begins-combining-two-words-spontaneously', 'communication'::domain, 'm13_24'::age_band, '21–24 months', 'Begins combining two words spontaneously', 21, 24, '{"try":"Model two-word combinations constantly — ‘more biscuit’, ‘daddy go’ — without requiring her to repeat them back.","watch":"Two words combined spontaneously and meaningfully, without prompting.","see":"No two-word combinations at all by 24 months."}'::jsonb),
  ('21-24-months-communication-follows-a-two-step-instruction-without-a-gesture-cue', 'communication'::domain, 'm13_24'::age_band, '21–24 months', 'Follows a two-step instruction without a gesture cue', 21, 24, '{"try":"Give two-step instructions using words alone, without pointing or demonstrating — ‘get your shoes and bring them here.’","watch":"She completes both steps from words alone, without a gesture to guide her.","see":"Not following even a one-step verbal instruction by 24 months."}'::jsonb),
  ('21-24-months-social_emotional-shows-empathy-toward-another-child-s-distress', 'social_emotional'::domain, 'm13_24'::age_band, '21–24 months', 'Shows empathy toward another child''s distress', 21, 24, '{"try":"Model empathy openly — comfort a crying stuffed animal, narrate feelings: ‘teddy''s sad, let''s give him a hug.’","watch":"She pats, hugs, or brings an object to a child or toy that seems upset.","see":"Not a standalone concern; worth noting only alongside other social delays."}'::jsonb),
  ('21-24-months-social_emotional-engages-in-brief-cooperative-play-with-an-adult', 'social_emotional'::domain, 'm13_24'::age_band, '21–24 months', 'Engages in brief cooperative play with an adult', 21, 24, '{"try":"Play simple back-and-forth games — rolling a ball, building then knocking down a tower together.","watch":"She takes a turn, waits for yours, then takes another — even briefly.","see":"No interest in any turn-based interaction by 24 months."}'::jsonb),
  ('21-24-months-social_emotional-has-frequent-intense-emotional-reactions', 'social_emotional'::domain, 'm13_24'::age_band, '21–24 months', 'Has frequent, intense emotional reactions', 21, 24, '{"try":"Stay calm and consistent through outbursts — name the feeling without trying to talk her out of it: ‘you''re really frustrated.’","watch":"Intense reactions that still resolve within a reasonable time with comfort.","see":"This is typical at this age — not a concern on its own."}'::jsonb),
  ('21-24-months-cognitive-names-a-few-familiar-objects-in-books-unprompted', 'cognitive'::domain, 'm13_24'::age_band, '21–24 months', 'Names a few familiar objects in books unprompted', 21, 24, '{"try":"Point and name everything in picture books daily. Ask ‘what''s that?’ and wait a moment before supplying the answer.","watch":"She names a picture in a book without you asking first.","see":"No naming of any pictures, even with prompting, by 24 months."}'::jsonb),
  ('21-24-months-cognitive-sorts-objects-by-one-clear-attribute', 'cognitive'::domain, 'm13_24'::age_band, '21–24 months', 'Sorts objects by one clear attribute', 21, 24, '{"try":"Use everyday objects — sort socks by colour, blocks by size. Keep it to one category at a time and narrate what you''re doing.","watch":"She groups two or more objects by a shared attribute like colour.","see":"No sorting or grouping behaviour at all by 24 months."}'::jsonb),
  ('21-24-months-cognitive-engages-in-short-pretend-play-sequences', 'cognitive'::domain, 'm13_24'::age_band, '21–24 months', 'Engages in short pretend-play sequences', 21, 24, '{"try":"Set up simple scenarios — pour pretend tea, feed a doll — and let her extend it in her own way.","watch":"She strings together two related pretend actions, like stirring then feeding.","see":"No pretend or symbolic play at all by 24 months warrants evaluation."}'::jsonb),
  ('24-27-months-motor-jumps-forward-with-both-feet-together', 'motor'::domain, 'm13_24'::age_band, '24–27 months', 'Jumps forward with both feet together', 24, 27, '{"try":"Demonstrate jumping off a low step with two feet together, counting ‘1, 2, 3, jump!’ A soft mat makes this safer to practise.","watch":"Both feet leave the ground together and land close to simultaneously.","see":"No jumping attempts at all by 27 months."}'::jsonb),
  ('24-27-months-motor-kicks-a-ball-with-reasonable-aim', 'motor'::domain, 'm13_24'::age_band, '24–27 months', 'Kicks a ball with reasonable aim', 24, 27, '{"try":"Set up a simple target — a box or a line — and encourage her to kick toward it. Large, slow balls are easiest to aim.","watch":"She kicks with some intentional direction, not just random contact.","see":"No ball play or lower-body coordination by 27 months."}'::jsonb),
  ('24-27-months-motor-walks-up-stairs-with-one-hand-held-feet-starting-to-alternate', 'motor'::domain, 'm13_24'::age_band, '24–27 months', 'Walks up stairs with one hand held, feet starting to alternate', 24, 27, '{"try":"Hold one hand rather than both on real stairs, narrating: ‘this foot, now that foot.’","watch":"Occasional alternating steps appearing, even if she still favours one-foot-per-step some of the time.","see":"No stair navigation at all, even with full support, by 27 months."}'::jsonb),
  ('24-27-months-communication-speaks-in-consistent-2-word-phrases', 'communication'::domain, 'm13_24'::age_band, '24–27 months', 'Speaks in consistent 2-word phrases', 24, 27, '{"try":"Model two-word combinations in every routine — ‘more milk’, ‘big dog’, ‘daddy go’ — and respond naturally rather than asking her to repeat.","watch":"Two-word phrases used spontaneously and meaningfully in daily conversation.","see":"No two-word combinations at all by 27 months warrants a speech check."}'::jsonb),
  ('24-27-months-communication-points-correctly-to-several-body-parts', 'communication'::domain, 'm13_24'::age_band, '24–27 months', 'Points correctly to several body parts', 24, 27, '{"try":"Play naming games at bath time or dressing — ‘where''s your nose? Your tummy?’ — pointing to your own first.","watch":"She reliably points to three or more named body parts.","see":"Cannot identify any body parts by name by 27 months."}'::jsonb),
  ('24-27-months-communication-begins-asking-simple-questions', 'communication'::domain, 'm13_24'::age_band, '24–27 months', 'Begins asking simple questions', 24, 27, '{"try":"Answer every ‘what''s that?’ simply and warmly, even when it''s repetitive — the asking itself is real cognitive work.","watch":"Simple questions appearing spontaneously, even in a two-word form like ‘what dat?’","see":"No questioning behaviour of any kind by 27 months."}'::jsonb),
  ('24-27-months-social_emotional-begins-brief-cooperative-play-with-a-peer', 'social_emotional'::domain, 'm13_24'::age_band, '24–27 months', 'Begins brief cooperative play with a peer', 24, 27, '{"try":"Set up simple joint activities — building a tower together — and narrate turn-taking: ‘my turn, your turn.’","watch":"She plays toward a shared goal with another child for a few minutes, even with adult support.","see":"No interest in cooperative activity with peers by 27 months."}'::jsonb),
  ('24-27-months-social_emotional-expresses-a-wider-vocabulary-of-feelings', 'social_emotional'::domain, 'm13_24'::age_band, '24–27 months', 'Expresses a wider vocabulary of feelings', 24, 27, '{"try":"Name feelings as they arise, using varied words — not just ‘happy’ and ‘sad’ but ‘excited’, ‘frustrated’, ‘tired’.","watch":"She uses or responds to a growing range of feeling words.","see":"Very limited emotional vocabulary or expression by 27 months."}'::jsonb),
  ('24-27-months-social_emotional-shows-pride-in-own-accomplishments', 'social_emotional'::domain, 'm13_24'::age_band, '24–27 months', 'Shows pride in own accomplishments', 24, 27, '{"try":"Celebrate her efforts specifically — ‘you built that all by yourself!’ — rather than generic praise.","watch":"She says or gestures ‘I did it!’ or seeks out your reaction after completing something.","see":"This is a healthy sign of self-awareness — not a concern."}'::jsonb),
  ('24-27-months-cognitive-counts-to-2-or-3-by-rote', 'cognitive'::domain, 'm13_24'::age_band, '24–27 months', 'Counts to 2 or 3 by rote', 24, 27, '{"try":"Count through daily routines — stairs, snacks, toys — out loud, consistently, so the sequence becomes familiar.","watch":"She recites ‘1, 2, 3’ in order, even without matching it to real objects yet.","see":"No number words or counting attempts at all by 27 months."}'::jsonb),
  ('24-27-months-cognitive-matches-identical-pictures-or-objects', 'cognitive'::domain, 'm13_24'::age_band, '24–27 months', 'Matches identical pictures or objects', 24, 27, '{"try":"Simple matching games — pairing identical picture cards or toys — build this skill quickly with repetition.","watch":"She pairs two identical items together with reasonable consistency.","see":"No matching behaviour at all, even with help, by 27 months."}'::jsonb),
  ('24-27-months-cognitive-engages-in-pretend-play-with-a-story-element', 'cognitive'::domain, 'm13_24'::age_band, '24–27 months', 'Engages in pretend play with a story element', 24, 27, '{"try":"Extend her pretend play with a simple narrative — ‘the doll is hungry, let''s feed her, now she''s sleepy.’","watch":"She links two or more pretend actions into a loose sequence.","see":"No pretend or symbolic play at all by 27 months warrants evaluation."}'::jsonb),
  ('27-30-months-motor-pedals-a-tricycle-with-effort', 'motor'::domain, 'm25_36'::age_band, '27–30 months', 'Pedals a tricycle with effort', 27, 30, '{"try":"Push the tricycle to get the pedalling motion going, then let her take over gradually. Many children need a few weeks of practice before it clicks.","watch":"She pushes the pedals with some coordination, even if inconsistent.","see":"No interest in or attempt at pedalling by 30 months."}'::jsonb),
  ('27-30-months-motor-stands-briefly-on-one-foot-with-support', 'motor'::domain, 'm25_36'::age_band, '27–30 months', 'Stands briefly on one foot with support', 27, 30, '{"try":"Hold her hand and encourage a brief one-foot balance during play — ‘can you stand like a flamingo?’","watch":"She balances on one foot for a second or two with your hand for support.","see":"No attempt at single-leg balance, even supported, by 30 months."}'::jsonb),
  ('27-30-months-motor-draws-vertical-and-horizontal-lines-intentionally', 'motor'::domain, 'm25_36'::age_band, '27–30 months', 'Draws vertical and horizontal lines intentionally', 27, 30, '{"try":"Draw a line slowly while she watches, then hand her the crayon and let her copy.","watch":"She produces a deliberate straight-ish line, not just random scribbles.","see":"No intentional line drawing at all by 30 months."}'::jsonb),
  ('27-30-months-communication-uses-simple-pronouns-even-if-mixed-up', 'communication'::domain, 'm25_36'::age_band, '27–30 months', 'Uses simple pronouns, even if mixed up', 27, 30, '{"try":"Model correct pronoun use naturally in your replies rather than correcting directly — the mix-ups resolve with exposure over time.","watch":"Pronouns like ‘I’, ‘me’, ‘you’ appearing in speech, even inconsistently.","see":"No pronoun use or self-reference at all by 30 months."}'::jsonb),
  ('27-30-months-communication-speaks-in-3-word-phrases-some-of-the-time', 'communication'::domain, 'm25_36'::age_band, '27–30 months', 'Speaks in 3-word phrases some of the time', 27, 30, '{"try":"Expand her 2-word phrases into 3 — if she says ‘more juice’, respond ‘yes, more apple juice.’","watch":"Occasional 3-word combinations appearing spontaneously alongside 2-word ones.","see":"No 2-word combinations at all by 30 months warrants a speech evaluation."}'::jsonb),
  ('27-30-months-communication-understands-simple-why-and-where-questions', 'communication'::domain, 'm25_36'::age_band, '27–30 months', 'Understands simple ‘why’ and ‘where’ questions', 27, 30, '{"try":"Ask simple questions during play and daily routines — ‘where''s your shoe?’ — and give her time to respond.","watch":"She responds appropriately to simple ‘where’ questions, even without full sentences.","see":"No response to simple questions at all by 30 months."}'::jsonb),
  ('27-30-months-social_emotional-takes-turns-with-heavy-adult-support', 'social_emotional'::domain, 'm25_36'::age_band, '27–30 months', 'Takes turns with heavy adult support', 27, 30, '{"try":"Use a visual or physical marker — a timer, a token — to make an abstract concept like ‘turns’ concrete and predictable.","watch":"She waits for her turn with active adult guidance, without major distress.","see":"No capacity for turn-taking even with significant support by 30 months."}'::jsonb),
  ('27-30-months-social_emotional-shows-early-signs-of-sharing-even-briefly', 'social_emotional'::domain, 'm25_36'::age_band, '27–30 months', 'Shows early signs of sharing, even briefly', 27, 30, '{"try":"Model sharing yourself — ‘here, you can have some of mine’ — and praise any spontaneous sharing warmly.","watch":"She offers a toy or object to another child or adult, even momentarily.","see":"This develops gradually through the preschool years — not a standalone concern yet."}'::jsonb),
  ('27-30-months-social_emotional-separates-from-a-caregiver-with-less-distress-in-familiar-settings', 'social_emotional'::domain, 'm25_36'::age_band, '27–30 months', 'Separates from a caregiver with less distress in familiar settings', 27, 30, '{"try":"Practise short, predictable separations in familiar places — always saying goodbye clearly rather than sneaking away.","watch":"She settles within a few minutes after a caregiver leaves in a known, safe setting.","see":"Extreme, prolonged distress at every separation by 30 months is worth discussing."}'::jsonb),
  ('27-30-months-cognitive-sorts-by-colour-reliably', 'cognitive'::domain, 'm25_36'::age_band, '27–30 months', 'Sorts by colour reliably', 27, 30, '{"try":"Sort toys, laundry, or snacks by colour together, narrating as you go: ‘red ones here, blue ones there.’","watch":"She consistently groups objects by colour with minimal prompting.","see":"No sorting by any attribute at all by 30 months."}'::jsonb),
  ('27-30-months-cognitive-understands-big-and-small', 'cognitive'::domain, 'm25_36'::age_band, '27–30 months', 'Understands ‘big’ and ‘small’', 27, 30, '{"try":"Use size words constantly in daily life — ‘big spoon, small spoon’ — and let her point to which is which.","watch":"She correctly identifies the bigger or smaller of two objects when asked.","see":"No understanding of size concepts at all by 30 months."}'::jsonb),
  ('27-30-months-cognitive-matches-an-object-to-its-picture-in-a-book', 'cognitive'::domain, 'm25_36'::age_band, '27–30 months', 'Matches an object to its picture in a book', 27, 30, '{"try":"Hold up a real object next to its picture in a book and ask ‘do these match?’","watch":"She connects a real object to its matching picture with reasonable consistency.","see":"No object-to-picture matching at all by 30 months."}'::jsonb),
  ('30-33-months-motor-jumps-off-a-low-step-with-both-feet', 'motor'::domain, 'm25_36'::age_band, '30–33 months', 'Jumps off a low step with both feet', 30, 33, '{"try":"Hold her hand for the first few attempts from a very low step, then let her try independently as confidence builds.","watch":"Both feet leave and land together, even if the landing is a bit wobbly.","see":"No jumping attempts of any kind by 33 months."}'::jsonb),
  ('30-33-months-motor-throws-a-ball-overhand-with-improving-aim', 'motor'::domain, 'm25_36'::age_band, '30–33 months', 'Throws a ball overhand with improving aim', 30, 33, '{"try":"Set up a simple target and take turns throwing toward it. Praise the effort and direction, not just accuracy.","watch":"She throws with a clear overhand motion and some intentional direction.","see":"Very limited throwing coordination by 33 months."}'::jsonb),
  ('30-33-months-motor-copies-a-simple-vertical-line-or-circular-shape', 'motor'::domain, 'm25_36'::age_band, '30–33 months', 'Copies a simple vertical line or circular shape', 30, 33, '{"try":"Draw a line or rough circle slowly while narrating, then hand her the crayon to copy.","watch":"A recognisable attempt at the shape, even if imperfect.","see":"No intentional shape-copying attempts at all by 33 months."}'::jsonb),
  ('30-33-months-communication-consistent-3-4-word-sentences', 'communication'::domain, 'm25_36'::age_band, '30–33 months', 'Consistent 3–4 word sentences', 30, 33, '{"try":"Expand every phrase she offers into a fuller sentence — if she says ‘more juice’, respond ‘yes, more apple juice, please.’","watch":"3–4 word sentences appearing regularly and spontaneously in conversation.","see":"Fewer than 50 words or no phrase combinations by 30 months warrants a speech evaluation."}'::jsonb),
  ('30-33-months-communication-asks-why-questions-frequently', 'communication'::domain, 'm25_36'::age_band, '30–33 months', 'Asks ‘why’ questions frequently', 30, 33, '{"try":"Answer every ‘why?’ simply and seriously — ‘because the leaves need water to grow.’ This questioning is exactly the cognitive work she should be doing.","watch":"Persistent, genuine questioning about cause and reason.","see":"This is healthy — not a concern at all."}'::jsonb),
  ('30-33-months-communication-follows-simple-two-step-instructions-reliably', 'communication'::domain, 'm25_36'::age_band, '30–33 months', 'Follows simple two-step instructions reliably', 30, 33, '{"try":"Build two-step instructions into daily routines — ‘wash your hands, then sit down’ — without repeating.","watch":"She completes both steps in order without needing a reminder partway through.","see":"Not following even one-step instructions by 33 months."}'::jsonb),
  ('30-33-months-social_emotional-engages-in-short-cooperative-play-with-a-peer', 'social_emotional'::domain, 'm25_36'::age_band, '30–33 months', 'Engages in short cooperative play with a peer', 30, 33, '{"try":"Set up simple joint activities — a shared puzzle, building a tower together — with light adult guidance.","watch":"She plays with another child toward a shared goal for several minutes.","see":"No interest in or engagement with peer play by 33 months."}'::jsonb),
  ('30-33-months-social_emotional-shows-early-guilt-or-concern-after-doing-something-wrong', 'social_emotional'::domain, 'm25_36'::age_band, '30–33 months', 'Shows early guilt or concern after doing something wrong', 30, 33, '{"try":"When something goes wrong, focus on repair, not punishment: ‘that hurt your friend — what can we do to help?’","watch":"She looks away, apologises, or tries to make amends after a mistake.","see":"Not a standalone concern; a complete absence is worth mentioning at a check-up."}'::jsonb),
  ('30-33-months-social_emotional-names-at-least-a-few-basic-emotions-in-self-or-others', 'social_emotional'::domain, 'm25_36'::age_band, '30–33 months', 'Names at least a few basic emotions in self or others', 30, 33, '{"try":"Narrate emotions in the moment and in books — ‘that made you sad’, ‘the bear in the story looks scared.’","watch":"She uses or responds to a few emotion words like happy, sad, or mad.","see":"No emotional vocabulary at all by 33 months."}'::jsonb),
  ('30-33-months-cognitive-counts-to-5-by-rote', 'cognitive'::domain, 'm25_36'::age_band, '30–33 months', 'Counts to 5 by rote', 30, 33, '{"try":"Count through daily routines beyond 3 — stairs, snacks, toys — consistently and out loud.","watch":"She recites ‘1 to 5’ in order, even without matching it to objects yet.","see":"Cannot count to 3 in any form by 33 months."}'::jsonb),
  ('30-33-months-cognitive-groups-objects-by-shape', 'cognitive'::domain, 'm25_36'::age_band, '30–33 months', 'Groups objects by shape', 30, 33, '{"try":"Sort a mixed pile of shapes together, narrating as you go: ‘circles here, squares there.’","watch":"She consistently groups objects by shape with minimal prompting.","see":"No sorting by any attribute at all by 33 months."}'::jsonb),
  ('30-33-months-cognitive-engages-in-multi-step-pretend-play', 'cognitive'::domain, 'm25_36'::age_band, '30–33 months', 'Engages in multi-step pretend play', 30, 33, '{"try":"Extend her pretend scenarios with a sequence — ‘feed the doll, now she''s sleepy, let''s tuck her in.’","watch":"She strings together two or more related pretend actions in order.","see":"No pretend or symbolic play at all by 33 months warrants evaluation."}'::jsonb),
  ('33-36-months-motor-walks-up-stairs-alternating-feet-independently', 'motor'::domain, 'm25_36'::age_band, '33–36 months', 'Walks up stairs alternating feet independently', 33, 36, '{"try":"Let her practise on real stairs with a rail, without holding your hand every time, when it''s safe to do so.","watch":"One foot per step going up, with little to no need for support.","see":"Still cannot navigate stairs at all by 3 years."}'::jsonb),
  ('33-36-months-motor-undresses-partially-without-help', 'motor'::domain, 'm25_36'::age_band, '33–36 months', 'Undresses partially without help', 33, 36, '{"try":"Give her time to attempt undressing even if it''s slow. Start with easy items — socks, loose shoes — before fastened clothing.","watch":"Removing socks, shoes, or a loose top independently with some effort.","see":"No attempt at self-undressing by 3 years."}'::jsonb),
  ('33-36-months-motor-copies-a-circle-with-a-crayon', 'motor'::domain, 'm25_36'::age_band, '33–36 months', 'Copies a circle with a crayon', 33, 36, '{"try":"Draw a large circle slowly while she watches, narrating the motion, then let her try on her own.","watch":"A roughly closed curved line — it doesn''t need to be a perfect circle.","see":"No intentional drawing or mark-making by 3 years."}'::jsonb),
  ('33-36-months-communication-speaks-in-3-4-word-sentences-understood-by-familiar-adults', 'communication'::domain, 'm25_36'::age_band, '33–36 months', 'Speaks in 3–4 word sentences understood by familiar adults', 33, 36, '{"try":"Have real back-and-forth conversations throughout the day, not just instructions — ask her real questions and wait for real answers.","watch":"Sentences understood by you and other familiar caregivers most of the time.","see":"Fewer than 50 words or no phrase combinations by 3 years warrants a speech evaluation."}'::jsonb),
  ('33-36-months-communication-uses-pronouns-like-i-me-you', 'communication'::domain, 'm25_36'::age_band, '33–36 months', 'Uses pronouns like ‘I’, ‘me’, ‘you’', 33, 36, '{"try":"Model correct pronoun use naturally in your replies — mix-ups are common and self-correct with exposure.","watch":"Pronouns appearing in speech, even if mixed up at first.","see":"No pronoun use or consistent self-reference by 3 years."}'::jsonb),
  ('33-36-months-communication-understands-two-to-three-step-instructions', 'communication'::domain, 'm25_36'::age_band, '33–36 months', 'Understands two-to-three step instructions', 33, 36, '{"try":"Give multi-step instructions in daily routines — ‘get your shoes, put them on, then come here’ — building from two steps to three.","watch":"She completes multi-step instructions in the right order without reminders.","see":"Not following two-step instructions by 3 years."}'::jsonb),
  ('33-36-months-social_emotional-begins-genuine-cooperative-play-toward-a-shared-goal', 'social_emotional'::domain, 'm25_36'::age_band, '33–36 months', 'Begins genuine cooperative play toward a shared goal', 33, 36, '{"try":"Set up simple joint activities — building a tower together, a team puzzle — and narrate taking turns.","watch":"She plays with another child toward a shared outcome, even briefly.","see":"No interest in other children or cooperative activity by 3 years."}'::jsonb),
  ('33-36-months-social_emotional-shows-a-wide-clear-range-of-emotional-expression', 'social_emotional'::domain, 'm25_36'::age_band, '33–36 months', 'Shows a wide, clear range of emotional expression', 33, 36, '{"try":"Name emotions as they happen — ‘you look really frustrated right now, that''s hard.’ This labelling is the first step toward regulation.","watch":"Clear expression of happiness, anger, sadness, fear, and excitement.","see":"Very flat affect or only one or two emotional expressions by 3 years."}'::jsonb),
  ('33-36-months-social_emotional-shows-real-interest-in-other-children-as-playmates', 'social_emotional'::domain, 'm25_36'::age_band, '33–36 months', 'Shows real interest in other children as playmates', 33, 36, '{"try":"Arrange regular contact with same-age children — playgroups, park time. Watching before joining in is completely fine.","watch":"She notices, watches, and approaches other children with curiosity.","see":"Complete indifference to or avoidance of other children by 3 years."}'::jsonb),
  ('33-36-months-cognitive-names-2-3-colours-correctly', 'cognitive'::domain, 'm25_36'::age_band, '33–36 months', 'Names 2–3 colours correctly', 33, 36, '{"try":"Name colours constantly in daily life — ‘your red shirt, the blue sky’ — without quizzing, just narrating.","watch":"She correctly names 2–3 colours when asked.","see":"No colour recognition at all by 3 years."}'::jsonb),
  ('33-36-months-cognitive-counts-up-to-3-objects-with-one-to-one-correspondence', 'cognitive'::domain, 'm25_36'::age_band, '33–36 months', 'Counts up to 3 objects with one-to-one correspondence', 33, 36, '{"try":"Count real objects together — grapes, stairs, toys — touching each one as you say its number.","watch":"She touches each object once while counting up to 3 accurately.","see":"No counting or one-to-one correspondence at all by 3 years."}'::jsonb),
  ('33-36-months-cognitive-engages-in-rich-make-believe-play-with-multiple-steps', 'cognitive'::domain, 'm25_36'::age_band, '33–36 months', 'Engages in rich make-believe play with multiple steps', 33, 36, '{"try":"Join her pretend play and extend it — if she''s cooking, ask what''s for dinner and where the plates are.","watch":"She creates a multi-step imaginative scenario with dolls, animals, or everyday objects.","see":"No pretend or symbolic play at all by 3 years warrants evaluation."}'::jsonb),
  ('3-4-years-motor-hops-on-one-foot', 'motor'::domain, 'm25_36'::age_band, '3–4 years', 'Hops on one foot', 36, 48, '{"try":"Make it a game — hop to the door, hop 3 times. Many children master hopping closer to 4 years, so stay patient.","watch":"At least 1–2 hops on each foot without putting the other foot down.","see":"Still unable to stand briefly on one foot by 4 years."}'::jsonb),
  ('3-4-years-motor-pedals-a-tricycle', 'motor'::domain, 'm25_36'::age_band, '3–4 years', 'Pedals a tricycle', 36, 48, '{"try":"Push her tricycle to get the sensation going, then let her take over. Most children need a few weeks of practice before the pedalling motion clicks.","watch":"She pedals smoothly and steers with reasonable control.","see":"Very limited leg coordination or strength by 4 years."}'::jsonb),
  ('3-4-years-motor-uses-scissors-with-support', 'motor'::domain, 'm25_36'::age_band, '3–4 years', 'Uses scissors (with support)', 36, 48, '{"try":"Use child-safe scissors on playdough first before paper — it requires the same motion with less frustration. Hold the paper steady while she cuts.","watch":"She opens and closes scissors and makes snips in paper with support.","see":"No fine motor control with tools by 4 years."}'::jsonb),
  ('3-4-years-motor-draws-a-person-with-2-body-parts', 'motor'::domain, 'm25_36'::age_band, '3–4 years', 'Draws a person with 2 body parts', 36, 48, '{"try":"Draw a simple person together and name the parts as you add them. Ask her to add a part: ‘What else does a person have?’","watch":"She draws a head with at least one other feature (eyes, legs, arms).","see":"No representational drawing by 4 years."}'::jsonb),
  ('3-4-years-motor-dresses-self-with-minimal-help', 'motor'::domain, 'm25_36'::age_band, '3–4 years', 'Dresses self with minimal help', 36, 48, '{"try":"Build dressing time into the routine — give her extra time so she can do it herself. Start with large buttons and elastic waists.","watch":"She puts on most items independently and asks for help only with complex fastenings.","see":"No attempt at independent dressing by 4 years."}'::jsonb),
  ('3-4-years-communication-speaks-in-full-sentences-4-6-words', 'communication'::domain, 'm25_36'::age_band, '3–4 years', 'Speaks in full sentences (4–6 words)', 36, 48, '{"try":"Engage in real conversations at mealtimes without screens. Ask open questions: ‘What was the best part of your day?’ rather than yes/no questions.","watch":"Consistent 4–6 word sentences with correct grammar most of the time.","see":"Sentences still mostly 2 words at 3.5 years warrants a speech assessment."}'::jsonb),
  ('3-4-years-communication-tells-simple-stories', 'communication'::domain, 'm25_36'::age_band, '3–4 years', 'Tells simple stories', 36, 48, '{"try":"Ask her to tell you about something that happened. Recap events together in sequence: ‘First we did… then we…’","watch":"She narrates a sequence of two or more events in order.","see":"No ability to retell a recent event by 4 years."}'::jsonb),
  ('3-4-years-communication-asks-how-and-when-questions', 'communication'::domain, 'm25_36'::age_band, '3–4 years', 'Asks ''how?'' and ''when?'' questions', 36, 48, '{"try":"Answer all questions genuinely and simply, even repetitive ones. These questions show she is building causal and temporal understanding.","watch":"A variety of question types — who, what, where, when, how — alongside ‘why?’","see":"No questioning at all by 3.5 years."}'::jsonb),
  ('3-4-years-communication-understands-same-and-different', 'communication'::domain, 'm25_36'::age_band, '3–4 years', 'Understands ''same'' and ''different''', 36, 48, '{"try":"Compare things together constantly: ‘This apple is red. Is this one the same colour or different?’ Make it a natural part of play.","watch":"She correctly identifies matching pairs and spots differences between objects.","see":"No concept of same/different by 4 years."}'::jsonb),
  ('3-4-years-social_emotional-shows-interest-in-friendships', 'social_emotional'::domain, 'm25_36'::age_band, '3–4 years', 'Shows interest in friendships', 36, 48, '{"try":"Facilitate regular playdates with the same children so friendships can form. Talk about her friends by name and show genuine interest in them.","watch":"She mentions specific children by name and asks to see them.","see":"Complete disinterest in peer relationships by 4 years."}'::jsonb),
  ('3-4-years-social_emotional-takes-turns-more-reliably', 'social_emotional'::domain, 'm25_36'::age_band, '3–4 years', 'Takes turns more reliably', 36, 48, '{"try":"Board games designed for this age are excellent — simple memory games, Snakes & Ladders. Rules give structure to turn-taking.","watch":"She waits her turn with only occasional reminders.","see":"Unable to take turns even with significant support by 4 years."}'::jsonb),
  ('3-4-years-social_emotional-understands-rules-of-simple-games', 'social_emotional'::domain, 'm25_36'::age_band, '3–4 years', 'Understands rules of simple games', 36, 48, '{"try":"Play simple rule-based games together every day. Explain rules slowly and be consistent — she is learning that rules apply to everyone, including you.","watch":"She follows game rules and appeals to rules when others break them.","see":"No understanding of rules or structured play by 4 years."}'::jsonb),
  ('3-4-years-social_emotional-shows-guilt-after-doing-wrong', 'social_emotional'::domain, 'm25_36'::age_band, '3–4 years', 'Shows guilt after doing wrong', 36, 48, '{"try":"When she does something wrong, focus on the behaviour not the person: ‘That hurt your friend. What can we do to help?’ Repair matters more than punishment.","watch":"She looks away, lowers her head, or spontaneously tries to make amends.","see":"Absence of any guilt response may be worth noting at your check-up."}'::jsonb),
  ('3-4-years-cognitive-counts-to-10', 'cognitive'::domain, 'm25_36'::age_band, '3–4 years', 'Counts to 10', 36, 48, '{"try":"Count through daily routines — stairs, grapes, steps to the door. The sequence needs to be heard hundreds of times before it becomes reliable.","watch":"She counts to 10 in sequence with one-to-one correspondence to objects.","see":"Cannot count to 5 by 4 years."}'::jsonb),
  ('3-4-years-cognitive-knows-first-and-last-name-age', 'cognitive'::domain, 'm25_36'::age_band, '3–4 years', 'Knows first and last name / age', 36, 48, '{"try":"Ask her name and age regularly in a fun way: ‘Excuse me, what is your name?’ Practise with relatives so it becomes natural.","watch":"She answers with her full name and age (or holds up correct fingers) reliably.","see":"Cannot state her first name by 4 years."}'::jsonb),
  ('3-4-years-cognitive-understands-time-concepts-yesterday-today', 'cognitive'::domain, 'm25_36'::age_band, '3–4 years', 'Understands time concepts (yesterday, today)', 36, 48, '{"try":"Use time words consistently: ‘Yesterday we went to the park. Today we are at home. Tomorrow is Sunday.’ A simple picture calendar makes this tangible.","watch":"She uses yesterday, today, and tomorrow approximately correctly.","see":"No time concept vocabulary by 4 years."}'::jsonb),
  ('3-4-years-cognitive-draws-recognisable-shapes', 'cognitive'::domain, 'm25_36'::age_band, '3–4 years', 'Draws recognisable shapes', 36, 48, '{"try":"Draw shapes together and name them. Playdough rolling into circles and snakes is great pre-drawing practice.","watch":"Circles, crosses, and rough squares appearing in her drawings.","see":"No intentional shapes in drawing by 4 years."}'::jsonb),
  ('4-5-years-motor-skips-and-gallops', 'motor'::domain, 'y3_5'::age_band, '4–5 years', 'Skips and gallops', 48, 60, '{"try":"Demonstrate skipping slowly and exaggeratedly. Most children master galloping first then skipping — both require alternating rhythmic movement.","watch":"She gallops with a consistent lead foot, or skips with alternating feet.","see":"Very limited gross motor coordination by 5 years."}'::jsonb),
  ('4-5-years-motor-catches-a-bounced-ball', 'motor'::domain, 'y3_5'::age_band, '4–5 years', 'Catches a bounced ball', 48, 60, '{"try":"Start with a large ball bounced from close range. Move further back as she improves. Two hands together first, then progress to one-handed.","watch":"She catches a bounced ball consistently with both hands from a metre away.","see":"No ball-catching ability by 5 years alongside other motor concerns."}'::jsonb),
  ('4-5-years-motor-writes-own-name', 'motor'::domain, 'y3_5'::age_band, '4–5 years', 'Writes own name', 48, 60, '{"try":"Write her name in dots for her to trace first. Use sandbox writing, finger paint, and chalk on pavements — gross motor versions of letter formation build the skill faster.","watch":"All letters of her name written in order, legibly enough to be recognisable.","see":"No letter formation at all by 5 years."}'::jsonb),
  ('4-5-years-motor-uses-fork-and-spoon-correctly', 'motor'::domain, 'y3_5'::age_band, '4–5 years', 'Uses fork and spoon correctly', 48, 60, '{"try":"Model correct grip at every meal and gently correct hold when needed. Thicker-handled cutlery is easier for small hands to grip.","watch":"She scoops and spears food reliably with a fork and spoon.","see":"Very limited utensil use by 5 years."}'::jsonb),
  ('4-5-years-motor-buttons-and-zips-clothing', 'motor'::domain, 'y3_5'::age_band, '4–5 years', 'Buttons and zips clothing', 48, 60, '{"try":"Practise with larger buttons first — dress-up clothes are ideal. A button frame (two pieces of fabric) lets her practise without the awkward angle of clothing on her own body.","watch":"She manages large buttons and a zip pull independently.","see":"Very limited fine motor development overall by 5 years."}'::jsonb),
  ('4-5-years-communication-speaks-clearly-to-strangers', 'communication'::domain, 'y3_5'::age_band, '4–5 years', 'Speaks clearly to strangers', 48, 60, '{"try":"Encourage her to order her own food, greet people, and answer simple questions from familiar adults. The more practice, the clearer her speech becomes.","watch":"Unfamiliar people understand her most of the time without you needing to translate.","see":"Strangers understand less than half of what she says by 4 years — seek a speech assessment."}'::jsonb),
  ('4-5-years-communication-recounts-recent-events-in-order', 'communication'::domain, 'y3_5'::age_band, '4–5 years', 'Recounts recent events in order', 48, 60, '{"try":"Ask about her day at a fixed time: ‘Tell me three things that happened today.’ Structure it the same way each time so she knows what to expect.","watch":"She narrates events in chronological order with beginning, middle, and end.","see":"Cannot sequence or retell events by 5 years."}'::jsonb),
  ('4-5-years-communication-understands-most-of-what-adults-say', 'communication'::domain, 'y3_5'::age_band, '4–5 years', 'Understands most of what adults say', 48, 60, '{"try":"Engage in full adult conversations in her presence. Include her — explain things genuinely rather than simplifying excessively.","watch":"She follows conversations, responds appropriately, and asks relevant questions.","see":"Frequent misunderstandings or failure to follow conversation by 5 years."}'::jsonb),
  ('4-5-years-communication-identifies-rhyming-words', 'communication'::domain, 'y3_5'::age_band, '4–5 years', 'Identifies rhyming words', 48, 60, '{"try":"Read rhyming books daily. Play ‘does that rhyme?’ games: ‘Cat and bat — do they rhyme?’ Make it playful.","watch":"She identifies when two words rhyme and can generate a rhyming word with prompting.","see":"No phonological awareness by 5 years needs assessment before school entry."}'::jsonb),
  ('4-5-years-social_emotional-has-preferred-friends', 'social_emotional'::domain, 'y3_5'::age_band, '4–5 years', 'Has preferred friends', 48, 60, '{"try":"Facilitate regular contact with the same children. Ask her about specific friends and remember their names — your interest signals that friendships matter.","watch":"She mentions specific friends by name and shows excitement about seeing them.","see":"No peer relationships at all by 5 years."}'::jsonb),
  ('4-5-years-social_emotional-follows-multi-step-rules-in-games', 'social_emotional'::domain, 'y3_5'::age_band, '4–5 years', 'Follows multi-step rules in games', 48, 60, '{"try":"Play board games with progressively complex rules. Involve her in reading the rules and explain why each rule exists.","watch":"She follows a 3–4 step rule set and reminds others of the rules.","see":"Cannot follow simple game rules by 5 years."}'::jsonb),
  ('4-5-years-social_emotional-expresses-feelings-with-words', 'social_emotional'::domain, 'y3_5'::age_band, '4–5 years', 'Expresses feelings with words', 48, 60, '{"try":"Model emotional vocabulary constantly: ‘I feel frustrated when the traffic is bad. What do you feel when that happens?’ Feelings charts expand the vocabulary.","watch":"She labels her own feelings with words rather than acting them out physically.","see":"No emotional vocabulary or exclusively physical emotional expression by 5 years."}'::jsonb),
  ('4-5-years-social_emotional-understands-fair-and-unfair', 'social_emotional'::domain, 'y3_5'::age_band, '4–5 years', 'Understands ''fair'' and ''unfair''', 48, 60, '{"try":"When situations arise, name the concept: ‘You feel that was unfair because she got more. Let us make it equal.’ Real situations teach this better than abstract lessons.","watch":"She uses ‘fair’ and ‘unfair’ appropriately and applies the concept to others.","see":"No understanding of fairness or equity by 5 years."}'::jsonb),
  ('4-5-years-cognitive-counts-to-20', 'cognitive'::domain, 'y3_5'::age_band, '4–5 years', 'Counts to 20', 48, 60, '{"try":"Count everything in daily life beyond 10. The teen numbers (11–19) are linguistically irregular in English — they need more repetition than 1–10.","watch":"She counts to 20 in sequence with reliable one-to-one correspondence to at least 10 objects.","see":"Cannot count reliably to 10 by 5 years."}'::jsonb),
  ('4-5-years-cognitive-recognises-letters-and-some-words', 'cognitive'::domain, 'y3_5'::age_band, '4–5 years', 'Recognises letters and some words', 48, 60, '{"try":"Point out letters in the environment — shop signs, cereal boxes, books. Her own name is the best starting point for letter recognition.","watch":"She recognises most letters of the alphabet by sight and reads a few high-frequency words.","see":"No letter recognition by 5 years needs assessment before school."}'::jsonb),
  ('4-5-years-cognitive-understands-sequencing-1st-2nd-3rd', 'cognitive'::domain, 'y3_5'::age_band, '4–5 years', 'Understands sequencing (1st, 2nd, 3rd)', 48, 60, '{"try":"Use ordinal words in daily routines: ‘You are first in the bath today. Your brother is second.’ Physical race games reinforce this naturally.","watch":"She uses first, second, and third correctly in context.","see":"No sequencing or ordinal number concept by 5 years."}'::jsonb),
  ('4-5-years-cognitive-sorts-by-multiple-attributes', 'cognitive'::domain, 'y3_5'::age_band, '4–5 years', 'Sorts by multiple attributes', 48, 60, '{"try":"Sort objects by two properties simultaneously: ‘Put the big red ones here, and the small red ones there.’ Sorting games make this concrete.","watch":"She can sort a group of objects by colour and size simultaneously.","see":"No sorting by single attribute by 5 years."}'::jsonb),
  ('5-6-years-motor-rides-a-bicycle-with-training-wheels', 'motor'::domain, 'y3_5'::age_band, '5–6 years', 'Rides a bicycle (with training wheels)', 60, 72, '{"try":"Start with a balance bike if possible — children who master balance first learn to pedal a real bike much faster. Training wheels are a valid alternative.","watch":"She pedals, steers, and brakes with reasonable confidence on training wheels.","see":"Very limited gross motor coordination by 6 years."}'::jsonb),
  ('5-6-years-motor-copies-complex-shapes-and-letters', 'motor'::domain, 'y3_5'::age_band, '5–6 years', 'Copies complex shapes and letters', 60, 72, '{"try":"Tracing books, dot-to-dot activities, and writing through sand or rice trays all build letter formation. Correct pencil grip now saves remediation later.","watch":"She copies all letters in her name and basic shapes (triangle, rectangle, diamond).","see":"Cannot copy simple shapes or letters by 6 years — an occupational therapy assessment may help."}'::jsonb),
  ('5-6-years-motor-ties-shoelaces-beginning', 'motor'::domain, 'y3_5'::age_band, '5–6 years', 'Ties shoelaces (beginning)', 60, 72, '{"try":"Use a lacing board or large practice shoe first. The ‘bunny ears’ method is often easier for young children than the traditional loop-swoop-pull.","watch":"She can make the first knot and attempt a bow, even with some help.","see":"Not a major concern if other fine motor skills are developing — laces are genuinely hard."}'::jsonb),
  ('5-6-years-motor-catches-a-small-ball-reliably', 'motor'::domain, 'y3_5'::age_band, '5–6 years', 'Catches a small ball reliably', 60, 72, '{"try":"Progress from a large soft ball to a smaller ball over weeks. Catching accuracy improves dramatically with repeated practice rather than instruction.","watch":"She catches a tennis-sized ball thrown from 2 metres away more often than not.","see":"Cannot catch any ball by 6 years alongside other motor concerns."}'::jsonb),
  ('5-6-years-motor-enjoys-active-physical-games', 'motor'::domain, 'y3_5'::age_band, '5–6 years', 'Enjoys active physical games', 60, 72, '{"try":"Ensure at least 60 minutes of active play every day. Unstructured outdoor play naturally includes running, jumping, climbing, and balancing.","watch":"She seeks out active play enthusiastically and keeps up physically with peers.","see":"Consistent avoidance of physical activity or significant physical fatigue by 6 years."}'::jsonb),
  ('5-6-years-communication-tells-detailed-stories', 'communication'::domain, 'y3_5'::age_band, '5–6 years', 'Tells detailed stories', 60, 72, '{"try":"Ask her to make up a story and you write it down exactly as she tells it. This validates her narrative voice and improves both length and complexity.","watch":"Stories with a character, a problem, and a resolution appearing naturally.","see":"Cannot construct a simple narrative by 6 years."}'::jsonb),
  ('5-6-years-communication-uses-future-tense-correctly', 'communication'::domain, 'y3_5'::age_band, '5–6 years', 'Uses future tense correctly', 60, 72, '{"try":"Talk about tomorrow and next week regularly: ‘On Saturday we will go to the market. What do you think we will find?’ Future planning in conversation builds tense.","watch":"Consistent and correct use of will/going to forms in natural speech.","see":"Major grammatical errors (wrong tense in all sentences) persisting at 6 years."}'::jsonb),
  ('5-6-years-communication-reads-simple-words-or-sentences', 'communication'::domain, 'y3_5'::age_band, '5–6 years', 'Reads simple words or sentences', 60, 72, '{"try":"Read together every single day for at least 20 minutes. Point to words as you read. Decodable phonics readers are designed to build this skill step by step.","watch":"She reads simple CVC words (cat, dog, sit) and high-frequency sight words reliably.","see":"No phonics awareness or word reading by 6 years needs a literacy assessment."}'::jsonb),
  ('5-6-years-communication-engages-in-conversations-with-adults', 'communication'::domain, 'y3_5'::age_band, '5–6 years', 'Engages in conversations with adults', 60, 72, '{"try":"Have genuine two-way conversations at meals. Ask her opinions and respond seriously. Mealtime conversation is one of the strongest predictors of vocabulary development.","watch":"She initiates conversation, stays on topic, and asks and answers questions naturally.","see":"Very limited conversational reciprocity by 6 years."}'::jsonb),
  ('5-6-years-social_emotional-distinguishes-real-from-pretend', 'social_emotional'::domain, 'y3_5'::age_band, '5–6 years', 'Distinguishes real from pretend', 60, 72, '{"try":"Talk about movies and stories: ‘Is that a real dinosaur or a pretend one? How do you know?’ This critical thinking develops gradually.","watch":"She correctly identifies fiction vs reality in books, TV, and play scenarios.","see":"Persistent confusion between reality and fantasy at 6 years may be worth discussing."}'::jsonb),
  ('5-6-years-social_emotional-shows-empathy-consistently', 'social_emotional'::domain, 'y3_5'::age_band, '5–6 years', 'Shows empathy consistently', 60, 72, '{"try":"Model empathy visibly — help others in front of her, discuss how characters in books might feel, respond empathetically to her own distress.","watch":"She spontaneously notices and responds to others’ emotional states.","see":"No empathy or emotional responsiveness to others by 6 years."}'::jsonb),
  ('5-6-years-social_emotional-negotiates-with-peers', 'social_emotional'::domain, 'y3_5'::age_band, '5–6 years', 'Negotiates with peers', 60, 72, '{"try":"Resist stepping in immediately during peer conflicts. Give her a chance to negotiate — then coach from the sideline if needed.","watch":"She uses words to propose compromises and reach agreement with peers.","see":"Exclusively aggressive or withdrawing responses to peer conflict by 6 years."}'::jsonb),
  ('5-6-years-social_emotional-has-a-best-friend', 'social_emotional'::domain, 'y3_5'::age_band, '5–6 years', 'Has a best friend', 60, 72, '{"try":"Facilitate consistent contact with potential friends. Talk about what makes a good friend and model friendship in your own relationships.","watch":"A specific child she consistently seeks out, talks about, and enjoys spending time with.","see":"No peer relationships or social connections at all by 6 years."}'::jsonb),
  ('5-6-years-cognitive-writes-letters-and-simple-words', 'cognitive'::domain, 'y3_5'::age_band, '5–6 years', 'Writes letters and simple words', 60, 72, '{"try":"Daily 10-minute writing practice is more effective than occasional long sessions. Start with her name, then high-frequency words. Correct grip and posture from the start.","watch":"All alphabet letters formed legibly; simple words written independently.","see":"Cannot write her own name legibly by 6 years."}'::jsonb),
  ('5-6-years-cognitive-adds-and-subtracts-to-10', 'cognitive'::domain, 'y3_5'::age_band, '5–6 years', 'Adds and subtracts to 10', 60, 72, '{"try":"Use objects, fingers, and everyday situations: ‘You have 4 grapes. I eat 2. How many are left?’ Concrete before abstract, always.","watch":"She solves simple addition and subtraction within 10 using objects or fingers reliably.","see":"No number sense or basic arithmetic by 6 years."}'::jsonb),
  ('5-6-years-cognitive-understands-cause-and-effect', 'cognitive'::domain, 'y3_5'::age_band, '5–6 years', 'Understands cause and effect', 60, 72, '{"try":"Talk through cause and effect in daily life and in stories: ‘Why did that happen? What could she have done differently?’ Open questions build this reasoning.","watch":"She explains ‘because’ correctly and predicts outcomes in familiar situations.","see":"No causal reasoning by 6 years."}'::jsonb),
  ('5-6-years-cognitive-classifies-objects-in-multiple-ways', 'cognitive'::domain, 'y3_5'::age_band, '5–6 years', 'Classifies objects in multiple ways', 60, 72, '{"try":"Sort the same set of objects in different ways: ‘Can we sort these another way?’ This flexibility of thinking is a precursor to mathematical and scientific reasoning.","watch":"She reclassifies the same objects by different criteria when asked.","see":"Very rigid, single-attribute thinking by 6 years."}'::jsonb)
